customer-web/src/services/catalog.servic.beforeText:
import { isSupabaseConfigured, supabase } from '../lib/supabase';
import {
  CatalogFacet,
  CatalogCategory,
  CatalogProduct,
  CatalogResponse,
  CatalogSummary,
  PublicMerchandisingResponse,
  PublicCatalogQuery,
  PublicConfigurableParcelOption,
  PublicConfigurableParcelResponse,
  PublicParcelComponentOption,
} from '../types/catalog';

type RawCatalogItem = Record<string, unknown>;

export const STOREFRONT_CATALOG_PAGE_SIZE = 24;
const STOREFRONT_CATALOG_MAX_PAGE_SIZE = 48;
export const STOREFRONT_CART_SNAPSHOT_BATCH_SIZE = 48;
export const STOREFRONT_PRODUCT_LINK_SEARCH_LIMIT = 8;

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export interface PublicProductLink {
  family: CatalogProduct;
  selectedProductId: string;
}

function textValue(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

function integerValue(value: unknown, fallback = 0): number {
  const numericValue = Number(value);
  return Number.isFinite(numericValue)
    ? Math.max(0, Math.floor(numericValue))
    : fallback;
}

export function resolveCatalogTotal(
  itemCount: number,
  serverTotal: unknown,
): number {
  return Math.max(itemCount, integerValue(serverTotal, itemCount));
}

export function mapCatalogProduct(item: RawCatalogItem): CatalogProduct {
  const unitsPerSalePackage = Math.max(
    1,
    integerValue(item.unitsPerSalePackage, 1)
  );
  const availableQuantity = integerValue(item.availableQuantity);
  const availableSalePackages = integerValue(
    item.availableSalePackages,
    Math.floor(availableQuantity / unitsPerSalePackage)
  );
  const salePackagePriceInMinorUnits = integerValue(
    item.salePackagePriceInMinorUnits
  );
  const salePriceInMinorUnits = integerValue(item.salePriceInMinorUnits);

  return {
    id: textValue(item.id),
    sku: textValue(item.sku),
    barcode: textValue(item.barcode),
    nameAr: textValue(item.nameAr) || 'صنف بدون اسم',
    description: textValue(item.description),
    categoryId: textValue(item.categoryId),
    categoryCode: textValue(item.categoryCode),
    categoryNameAr: textValue(item.categoryNameAr) || 'أصناف متنوعة',
    brandId: textValue(item.brandId),
    brandNameAr: textValue(item.brandNameAr),
    unitId: textValue(item.unitId),
    unitNameAr: textValue(item.unitNameAr) || 'باكيت',
    saleUnitId: textValue(item.saleUnitId),
    saleUnitNameAr: textValue(item.saleUnitNameAr) || 'طرد',
    unitsPerSalePackage,
    parcelOnly: item.parcelOnly === true,
    salePriceInMinorUnits,
    salePackagePriceInMinorUnits,
    availableQuantity,
    availableSalePackages,
    minimumOrderPackages: Math.max(
      1,
      integerValue(item.minimumOrderPackages, 1)
    ),
    imageUrl: textValue(item.imageUrl),
    isAvailable:
      item.isAvailable === true &&
      availableSalePackages > 0 &&
      salePackagePriceInMinorUnits > 0,
    createdAt: textValue(item.createdAt),
    soldPackagesLast90Days: integerValue(item.soldPackagesLast90Days),
    isFlavorMaster: item.isFlavorMaster === true,
    flavorMasterProductId: textValue(item.flavorMasterProductId),
    flavorNameAr: textValue(item.flavorNameAr),
    flavorSortOrder: integerValue(item.flavorSortOrder),
    variants: [],
  };
}

const mapParcelComponent = (value: unknown): PublicParcelComponentOption | null => {
  const component = value && typeof value === 'object' && !Array.isArray(value)
    ? value as RawCatalogItem
    : {};
  const productId = textValue(component.productId);
  const availableQuantity = integerValue(component.availableQuantity);
  if (!UUID_PATTERN.test(productId) || availableQuantity < 0) return null;
  return {
    productId,
    sku: textValue(component.sku),
    nameAr: textValue(component.nameAr) || 'نكهة',
    flavorNameAr: textValue(component.flavorNameAr),
    unitNameAr: textValue(component.unitNameAr) || 'وحدة',
    imageUrl: textValue(component.imageUrl),
    availableQuantity,
  };
};

const mapParcelOption = (value: unknown): PublicConfigurableParcelOption | null => {
  const option = value && typeof value === 'object' && !Array.isArray(value)
    ? value as RawCatalogItem
    : {};
  const familyProductId = textValue(option.familyProductId);
  const parcelConfigurationId = textValue(option.parcelConfigurationId);
  const configurationRevision = integerValue(option.configurationRevision);
  const unitsPerParcel = integerValue(option.unitsPerParcel);
  const parcelPriceInMinorUnits = integerValue(option.parcelPriceInMinorUnits);
  const components = (Array.isArray(option.components) ? option.components : [])
    .map(mapParcelComponent)
    .filter((item): item is PublicParcelComponentOption => Boolean(item));
  if (
    !UUID_PATTERN.test(familyProductId) ||
    !UUID_PATTERN.test(parcelConfigurationId) ||
    option.compositionMode !== 'configurable_mix' ||
    configurationRevision < 1 ||
    unitsPerParcel < 1 ||
    parcelPriceInMinorUnits < 1 ||
    components.length === 0
  ) return null;
  return {
    familyProductId,
    parcelConfigurationId,
    configurationRevision,
    compositionMode: 'configurable_mix',
    unitsPerParcel,
    parcelPriceInMinorUnits,
    baseUnitNameAr: textValue(option.baseUnitNameAr) || 'وحدة',
    saleUnitNameAr: textValue(option.saleUnitNameAr) || 'طرد',
    components,
  };
};

/** Reads only the bounded guest-safe projection created by Migration 117. */
export async function fetchPublicConfigurableParcelOptions(
  familyProductIds: string[]
): Promise<PublicConfigurableParcelResponse> {
  const requestedIds = Array.from(new Set(familyProductIds.filter((id) => UUID_PATTERN.test(id))));
  if (requestedIds.length < 1 || requestedIds.length > 48) {
    throw new Error('تعذر تحديد عائلة الطرد المطلوبة.');
  }
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بكتالوج Supabase غير مكتملة في موقع العملاء.');
  }
  const { data, error } = await supabase.rpc(
    'get_public_configurable_parcel_options',
    { p_family_product_ids: requestedIds }
  );
  if (error) throw new Error(error.message || 'تعذر تحميل خيارات الطرد.');
  const payload = data && typeof data === 'object' && !Array.isArray(data)
    ? data as RawCatalogItem
    : {};
  const featureState = payload.featureState;
  if (!['OFF', 'OWNER_PILOT', 'ENABLED'].includes(String(featureState))) {
    throw new Error('تعذر التحقق من حالة ميزة الطرود.');
  }
  const options = (Array.isArray(payload.options) ? payload.options : [])
    .map(mapParcelOption)
    .filter((item): item is PublicConfigurableParcelOption => Boolean(item));
  return {
    featureState: featureState as PublicConfigurableParcelResponse['featureState'],
    guestCreationEnabled: payload.guestCreationEnabled === true,
    options,
  };
}

function mapCatalogItems(value: unknown): CatalogProduct[] {
  const rawItems = Array.isArray(value) ? value : [];
  const flatItems = rawItems
    .map((item) => mapCatalogProduct(item as RawCatalogItem))
    .filter(
      (item: CatalogProduct) =>
        Boolean(item.id) &&
        Boolean(item.saleUnitId) &&
        item.unitsPerSalePackage > 0 &&
        item.salePackagePriceInMinorUnits > 0
    );
  return groupCatalogFlavorFamilies(flatItems);
}

export function mapPublicMerchandisingResponse(
  value: unknown,
): PublicMerchandisingResponse {
  const payload = value && typeof value === 'object' && !Array.isArray(value)
    ? value as RawCatalogItem
    : {};
  return {
    newest: mapCatalogItems(payload.newest),
    bestSellers: mapCatalogItems(payload.bestSellers),
    offers: mapCatalogItems(payload.offers),
    lowStock: mapCatalogItems(payload.lowStock),
  };
}

export function groupCatalogFlavorFamilies(
  flatProducts: CatalogProduct[]
): CatalogProduct[] {
  const childrenByMaster = new Map<string, CatalogProduct[]>();
  flatProducts.forEach((product) => {
    if (!product.flavorMasterProductId) return;
    const current = childrenByMaster.get(product.flavorMasterProductId) || [];
    current.push(product);
    childrenByMaster.set(product.flavorMasterProductId, current);
  });

  const roots = flatProducts.filter((product) => !product.flavorMasterProductId);
  const rootsById = new Map(roots.map((product) => [product.id, product]));

  // Search may return a matching flavor without its parent row. Build a safe
  // family card from the flavor so the result still stays grouped.
  childrenByMaster.forEach((children, masterId) => {
    if (rootsById.has(masterId) || children.length === 0) return;
    const first = children[0];
    const suffix = first.flavorNameAr ? ` - ${first.flavorNameAr}` : '';
    const familyName =
      suffix && first.nameAr.endsWith(suffix)
        ? first.nameAr.slice(0, -suffix.length)
        : first.nameAr;
    const syntheticRoot: CatalogProduct = {
      ...first,
      id: masterId,
      sku: masterId,
      barcode: '',
      nameAr: familyName,
      flavorMasterProductId: '',
      flavorNameAr: '',
      isFlavorMaster: true,
      variants: [],
    };
    roots.push(syntheticRoot);
    rootsById.set(masterId, syntheticRoot);
  });

  return roots.map((root) => {
    const variants = [...(childrenByMaster.get(root.id) || [])].sort(
      (first, second) =>
        first.flavorSortOrder - second.flavorSortOrder ||
        first.flavorNameAr.localeCompare(second.flavorNameAr, 'ar')
    );
    if (variants.length === 0) return root;

    return {
      ...root,
      isFlavorMaster: true,
      variants,
      imageUrl: root.imageUrl || variants.find((item) => item.imageUrl)?.imageUrl || '',
      availableQuantity: variants.reduce(
        (sum, item) => sum + item.availableQuantity,
        0
      ),
      availableSalePackages: variants.reduce(
        (sum, item) => sum + item.availableSalePackages,
        0
      ),
      isAvailable: variants.some((item) => item.isAvailable),
      soldPackagesLast90Days: variants.reduce(
        (sum, item) => sum + item.soldPackagesLast90Days,
        0
      ),
    };
  });
}

export function mapCatalogCategory(item: RawCatalogItem): CatalogCategory {
  return {
    id: textValue(item.id),
    code: textValue(item.code),
    nameAr: textValue(item.nameAr) || 'قسم بدون اسم',
    imageUrl: textValue(item.imageUrl),
    productCount: integerValue(item.productCount),
    availableProductCount: integerValue(item.availableProductCount),
  };
}

function mapCatalogFacet(item: RawCatalogItem): CatalogFacet {
  return {
    id: textValue(item.id),
    nameAr: textValue(item.nameAr) || 'غير مسمى',
  };
}

function mapCatalogSummary(value: unknown): CatalogSummary {
  const rawSummary = value && typeof value === 'object'
    ? value as RawCatalogItem
    : {};
  return {
    availableProducts: integerValue(rawSummary.availableProducts),
    availableSalePackages: integerValue(rawSummary.availableSalePackages),
    lowStockProducts: integerValue(rawSummary.lowStockProducts),
  };
}

export function deriveCatalogCategories(
  products: CatalogProduct[]
): CatalogCategory[] {
  const categories = new Map<string, CatalogCategory>();

  products.forEach((product) => {
    if (!product.categoryId) return;
    const current = categories.get(product.categoryId);
    categories.set(product.categoryId, {
      id: product.categoryId,
      code: product.categoryCode,
      nameAr: product.categoryNameAr,
      imageUrl: '',
      productCount: (current?.productCount ?? 0) + 1,
      availableProductCount:
        (current?.availableProductCount ?? 0) +
        (product.isAvailable ? 1 : 0),
    });
  });

  return Array.from(categories.values()).sort((first, second) =>
    first.nameAr.localeCompare(second.nameAr, 'ar')
  );
}

export function buildCartSnapshotBatches(productIds: string[]): string[][] {
  const uniqueProductIds = Array.from(
    new Set(productIds.filter((productId) => Boolean(productId)))
  );
  const batches: string[][] = [];
  for (
    let index = 0;
    index < uniqueProductIds.length;
    index += STOREFRONT_CART_SNAPSHOT_BATCH_SIZE
  ) {
    batches.push(
      uniqueProductIds.slice(index, index + STOREFRONT_CART_SNAPSHOT_BATCH_SIZE)
    );
  }
  return batches;
}

/** Finds the exact family and sellable product addressed by a public link. */
export function findPublicProductLink(
  products: CatalogProduct[],
  productKey: string
): PublicProductLink | null {
  const normalizedKey = productKey.trim();
  if (!normalizedKey) return null;

  for (const family of products) {
    const matchedProduct = [family, ...family.variants].find(
      (product) => product.id === normalizedKey || product.sku === normalizedKey
    );
    if (matchedProduct) {
      return { family, selectedProductId: matchedProduct.id };
    }
  }

  return null;
}

export async function fetchPublicProductCatalog(
  query: PublicCatalogQuery = {}
): Promise<CatalogResponse> {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error(
      'إعدادات الاتصال بكتالوج Supabase غير مكتملة في موقع العملاء.'
    );
  }

  const requestedLimit = Math.min(
    STOREFRONT_CATALOG_MAX_PAGE_SIZE,
    Math.max(1, Math.floor(query.limit ?? STOREFRONT_CATALOG_PAGE_SIZE))
  );
  const { data, error } = await supabase.rpc('get_public_storefront_catalog_page', {
    p_limit: requestedLimit,
    p_offset: Math.max(0, Math.floor(query.offset ?? 0)),
    p_category_id: query.categoryId || null,
    p_search: query.searchQuery?.trim() || null,
    p_availability: query.availability ?? 'all',
    p_sort: query.sort ?? 'recommended',
    p_brand_id: query.brandId || null,
    p_sale_unit_id: query.saleUnitId || null,
    p_product_ids: query.productIds?.filter(Boolean) ?? null,
  });

  if (error) {
    throw new Error(error.message || 'تعذر تحميل كتالوج الجملة.');
  }

  const items = mapCatalogItems(data?.items);
  const rawCategories = Array.isArray(data?.categories)
    ? data.categories
    : [];
  const mappedCategories: CatalogCategory[] = rawCategories
    .map((item: RawCatalogItem) => mapCatalogCategory(item))
    .filter(
      (category: CatalogCategory) =>
        Boolean(category.id) && Boolean(category.nameAr)
    );

  const rawBrands = Array.isArray(data?.brands) ? data.brands : [];
  const rawSaleUnits = Array.isArray(data?.saleUnits) ? data.saleUnits : [];
  const categories = mappedCategories.length > 0
    ? mappedCategories
    : deriveCatalogCategories(items);

  return {
    items,
    categories,
    brands: rawBrands
      .map((item: RawCatalogItem) => mapCatalogFacet(item))
      .filter((item: CatalogFacet) => Boolean(item.id)),
    saleUnits: rawSaleUnits
      .map((item: RawCatalogItem) => mapCatalogFacet(item))
      .filter((item: CatalogFacet) => Boolean(item.id)),
    summary: mapCatalogSummary(data?.summary),
    total: resolveCatalogTotal(items.length, data?.total),
    limit: integerValue(data?.limit, requestedLimit),
    offset: integerValue(data?.offset),
  };
}

/**
 * Loads all home merchandising rails in one bounded server response. The
 * response contains at most six product families per rail and no catalog facets.
 */
export async function fetchPublicStorefrontMerchandising(): Promise<PublicMerchandisingResponse> {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بكتالوج Supabase غير مكتملة في موقع العملاء.');
  }

  const { data, error } = await supabase.rpc('get_public_storefront_merchandising');
  if (error) {
    throw new Error(error.message || 'تعذر تحميل الاختيارات المميزة.');
  }

  return mapPublicMerchandisingResponse(data);
}

/**
 * Resolves a share link with one bounded public catalog request. UUID links
 * use the exact product-ID contract; SKU links use server-side catalog search
 * and are accepted only when an exact result match is returned.
 */
export async function fetchPublicProductLink(
  productKey: string
): Promise<PublicProductLink | null> {
  const normalizedKey = productKey.trim();
  if (!normalizedKey) return null;

  try {
    const response = await fetchPublicProductCatalog(
      UUID_PATTERN.test(normalizedKey)
        ? { limit: 1, productIds: [normalizedKey] }
        : {
            limit: STOREFRONT_PRODUCT_LINK_SEARCH_LIMIT,
            searchQuery: normalizedKey,
          }
    );
    return findPublicProductLink(response.items, normalizedKey);
  } catch {
    throw new Error('تعذر فتح هذا المنتج الآن. حاول مرة أخرى.');
  }
}

/**
 * Reads only the cart's exact sellable product IDs. The catalog RPC groups
 * flavor families for rendering, so flatten the response back to sellable
 * rows before reconciling the cart by product ID.
 */
export async function fetchPublicCartSnapshot(
  productIds: string[]
): Promise<CatalogProduct[]> {
  const batches = buildCartSnapshotBatches(productIds);
  if (batches.length === 0) return [];

  try {
    const responses = await Promise.all(
      batches.map((productIdsBatch) =>
        fetchPublicProductCatalog({
          limit: productIdsBatch.length,
          productIds: productIdsBatch,
        })
      )
    );
    return responses.flatMap((response) =>
      response.items.flatMap((product) =>
        product.variants.length > 0 ? product.variants : [product]
      )
    );
  } catch {
    throw new Error('تعذر التحقق من سعر ومخزون السلة. حاول مرة أخرى.');
  }
}

customer-web/src/services/orders.service.beforeText:
import {
  invokePublicEdgeFunction,
  isSupabaseConfigured,
  supabase,
} from '../lib/supabase';
import {
  GuestOrderReceipt,
  GuestOrderRequest,
  GuestOrderTracking,
  GuestPromotionQuote,
  GuestPromotionQuoteV2,
  GuestOrderV2Line,
} from '../types/checkout';
import {
  buildDeliveryAddress,
  MAX_GUEST_DELIVERY_DETAILS_LENGTH,
  normalizeJordanPhone,
} from '../utils/checkout';

type RpcPayload = Record<string, unknown>;

function stringValue(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

function integerValue(value: unknown): number {
  const numericValue = Number(value);
  return Number.isFinite(numericValue)
    ? Math.max(0, Math.round(numericValue))
    : 0;
}

export function mapGuestOrderReceipt(data: RpcPayload): GuestOrderReceipt {
  if (data.success !== true) {
    throw new Error(
      stringValue(data.message) || 'تعذر تسجيل الطلب في نظام الإدارة.'
    );
  }

  const orderNumber = stringValue(data.order_number);
  const orderId = stringValue(data.order_id);
  if (!orderNumber || !orderId) {
    throw new Error('تم استلام رد غير مكتمل عند إنشاء الطلب.');
  }

  return {
    success: true,
    id: orderId,
    orderNumber,
    customerId: stringValue(data.customer_id),
    customerAddressId: stringValue(data.customer_address_id),
    customerReused: data.customer_reused === true,
    idempotentReplay: data.idempotent_replay === true,
    subtotalInMinorUnits: integerValue(data.subtotal),
    discountInMinorUnits: integerValue(data.discount),
    totalInMinorUnits: integerValue(data.total),
    deliveryFeeInMinorUnits: integerValue(data.delivery_fee),
    deliveryZone:
      data.delivery_zone === 'outside_ramtha'
        ? 'outside_ramtha'
        : 'inside_ramtha',
    promotionCode: stringValue(data.promotion_code),
    status: stringValue(data.status) || 'new',
    paymentMethod:
      data.payment_method === 'cliq' ? 'cliq' : 'cash_on_delivery',
    trackingToken: stringValue(data.tracking_token) || undefined,
    trackingPath: stringValue(data.tracking_path) || undefined,
    message:
      stringValue(data.message) || 'تم تسجيل الطلب في نظام الإدارة بنجاح.',
  };
}

export function mapGuestPromotionQuote(
  data: RpcPayload
): GuestPromotionQuote {
  if (data.success !== true) {
    throw new Error(
      stringValue(data.message) || 'تعذر التحقق من رمز الخصم.'
    );
  }

  const code = stringValue(data.code);
  const promotionCodeId = stringValue(data.promotion_code_id);
  if (!code || !promotionCodeId) {
    throw new Error('تم استلام رد غير مكتمل عند التحقق من الخصم.');
  }

  return {
    success: true,
    promotionCodeId,
    code,
    description: stringValue(data.description),
    subtotalInMinorUnits: integerValue(data.subtotal),
    discountInMinorUnits: integerValue(data.discount),
    totalInMinorUnits: integerValue(data.total),
    message: stringValue(data.message) || 'تم تطبيق رمز الخصم.',
  };
}

export function mapGuestPromotionQuoteV2(data: RpcPayload): GuestPromotionQuoteV2 {
  if (
    data.success !== true ||
    data.contractVersion !== 'phase3-customer-promotion-preview-v2'
  ) {
    throw new Error(stringValue(data.message) || 'تعذر التحقق من إجمالي الطلب.');
  }
  const promotion = data.promotion && typeof data.promotion === 'object'
    ? data.promotion as RpcPayload
    : {};
  return {
    success: true,
    contractVersion: 'phase3-customer-promotion-preview-v2',
    code: stringValue(promotion.code),
    description: stringValue(promotion.descriptionAr),
    subtotalInMinorUnits: integerValue(data.merchandiseSubtotalInMinorUnits),
    discountInMinorUnits: integerValue(data.promotionDiscountInMinorUnits),
    totalInMinorUnits: integerValue(data.finalMerchandiseTotalInMinorUnits),
    message: stringValue(promotion.code) ? 'تم تطبيق رمز الخصم.' : 'تم التحقق من أسعار الطلب.',
  };
}

export async function previewGuestPromotionV2(
  lines: GuestOrderV2Line[],
  code?: string,
  customerPhone?: string
): Promise<GuestPromotionQuoteV2> {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بـ Supabase غير مكتملة.');
  }
  const normalizedPhone = customerPhone ? normalizeJordanPhone(customerPhone) : null;
  const { data, error } = await supabase.rpc('preview_guest_promotion_v2', {
    p_lines: lines,
    p_promotion_code: code?.trim() || null,
    p_customer_phone: normalizedPhone,
  });
  if (error) throw new Error(error.message || 'تعذر التحقق من إجمالي الطلب.');
  return mapGuestPromotionQuoteV2((data || {}) as RpcPayload);
}

export async function previewGuestPromotion(
  code: string,
  items: GuestOrderRequest['items'],
  customerPhone?: string
): Promise<GuestPromotionQuote> {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بـ Supabase غير مكتملة.');
  }

  const normalizedPhone = customerPhone
    ? normalizeJordanPhone(customerPhone)
    : null;
  const { data, error } = await supabase.rpc(
    'preview_guest_promotion',
    {
      p_code: code,
      p_items: items,
      p_customer_phone: normalizedPhone,
    }
  );

  if (error) {
    throw new Error(error.message || 'تعذر التحقق من رمز الخصم.');
  }

  return mapGuestPromotionQuote((data || {}) as RpcPayload);
}

export async function submitGuestCustomerOrder(
  request: GuestOrderRequest
): Promise<GuestOrderReceipt> {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بـ Supabase غير مكتملة.');
  }

  const normalizedPhone = normalizeJordanPhone(request.customer.phone);
  if (!normalizedPhone) {
    throw new Error('رقم الهاتف الأردني غير صحيح.');
  }

  const deliveryAddress = buildDeliveryAddress(request.customer);
  if (!deliveryAddress || deliveryAddress.length > MAX_GUEST_DELIVERY_DETAILS_LENGTH) {
    throw new Error(`تفاصيل العنوان والتوصيل يجب ألا تتجاوز ${MAX_GUEST_DELIVERY_DETAILS_LENGTH} حرفًا.`);
  }

  const data = await invokePublicEdgeFunction<RpcPayload>(
    'submit-guest-order',
    {
      contractVersion: request.contractVersion,
      idempotencyKey: request.idempotencyKey,
      turnstileToken: request.turnstileToken,
      clientSessionId: request.clientSessionId,
      customer: {
        ...request.customer,
        fullName: request.customer.fullName.trim(),
        phone: normalizedPhone,
        governorate: request.customer.governorate.trim(),
        city: request.customer.city.trim(),
        area: request.customer.area.trim(),
        street: request.customer.street.trim(),
        building: request.customer.building.trim(),
        addressNotes: request.customer.addressNotes.trim(),
        googleMapsUrl: request.customer.googleMapsUrl.trim(),
        customerNotes: request.customer.customerNotes.trim(),
      },
      items: request.items,
      promotionCode: request.promotionCode?.trim() || null,
      paymentMethod: request.paymentMethod,
      deliveryZone: request.deliveryZone,
      expectedQuote: request.expectedQuote,
    }
  );

  return mapGuestOrderReceipt(data);
}

function mapGuestOrderTracking(payload: RpcPayload): GuestOrderTracking {
  if (payload.success !== true) {
    throw new Error(stringValue(payload.message) || 'لم نعثر على الطلب بهذه البيانات.');
  }

  const rawTimeline = Array.isArray(payload.timeline) ? payload.timeline : [];
  return {
    success: true,
    orderNumber: stringValue(payload.order_number),
    status: stringValue(payload.status),
    paymentMethod:
      payload.payment_method === 'cliq' ? 'cliq' : 'cash_on_delivery',
    paymentStatus: stringValue(payload.payment_status) || 'unpaid',
    totalInMinorUnits: integerValue(payload.total),
    itemCount: integerValue(payload.item_count),
    createdAt: stringValue(payload.created_at),
    updatedAt: stringValue(payload.updated_at),
    trackingToken: stringValue(payload.tracking_token),
    trackingPath: stringValue(payload.tracking_path),
    deliveryStartedAt: stringValue(payload.delivery_started_at) || undefined,
    estimatedArrivalAt:
      stringValue(payload.estimated_arrival_at) || undefined,
    deliveryCompletedAt:
      stringValue(payload.delivery_completed_at) || undefined,
    driverPhone: stringValue(payload.driver_phone) || undefined,
    timeline: rawTimeline.map((entry) => {
      const value = (entry || {}) as RpcPayload;
      return {
        status: stringValue(value.status),
        createdAt: stringValue(value.created_at),
      };
    }),
  };
}

export async function trackGuestOrder(
  orderNumber: string,
  phone: string
): Promise<GuestOrderTracking> {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بـ Supabase غير مكتملة.');
  }

  const normalizedPhone = normalizeJordanPhone(phone);
  if (!normalizedPhone) throw new Error('رقم الهاتف الأردني غير صحيح.');

  const { data, error } = await supabase.rpc('track_guest_order', {
    p_order_number: orderNumber.trim().toUpperCase(),
    p_customer_phone: normalizedPhone,
  });
  if (error) throw new Error(error.message || 'تعذر متابعة الطلب.');
  return mapGuestOrderTracking((data || {}) as RpcPayload);
}

export async function trackGuestOrderByToken(
  trackingToken: string
): Promise<GuestOrderTracking> {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بـ Supabase غير مكتملة.');
  }

  const { data, error } = await supabase.rpc('track_guest_order_by_token', {
    p_tracking_token: trackingToken.trim(),
  });
  if (error) throw new Error(error.message || 'تعذر فتح رابط متابعة الطلب.');
  return mapGuestOrderTracking((data || {}) as RpcPayload);
}

customer-web/src/services/receipts.servi.beforeText:
import { isSupabaseConfigured, supabase } from '../lib/supabase';
import type { PublicPosReceipt } from '../types/receipt';
import {parseExchangeFunding} from '../receipts/exchangeFunding';

type RpcRecord = Record<string, unknown>;

const recordValue = (value: unknown): RpcRecord =>
  value && typeof value === 'object' && !Array.isArray(value)
    ? (value as RpcRecord)
    : {};
const stringValue = (value: unknown) =>
  typeof value === 'string' ? value : '';
const integerValue = (value: unknown) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.trunc(parsed) : 0;
};

export async function fetchPublicPosReceipt(
  receiptToken: string
): Promise<PublicPosReceipt> {
  if (!isSupabaseConfigured || !supabase) {
    throw new Error('إعدادات الاتصال بـ Supabase غير مكتملة.');
  }
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(receiptToken)) {
    throw new Error('رابط الإيصال غير صحيح.');
  }

  const { data, error } = await supabase.rpc('get_public_pos_receipt', {
    p_receipt_token: receiptToken,
  });
  if (error) throw new Error(error.message || 'تعذر تحميل الإيصال.');

  const payload = recordValue(data);
  if (payload.success !== true) {
    throw new Error(stringValue(payload.message) || 'الإيصال غير موجود.');
  }

  const branch = recordValue(payload.branch);
  const hasInitial=payload.initialPaymentMethod!==undefined;
  if(hasInitial&&(!['cash','cliq'].includes(String(payload.initialPaymentMethod))
    ||!Number.isSafeInteger(payload.amountPaidInMinorUnits)||Number(payload.amountPaidInMinorUnits)<0
    ||!Number.isSafeInteger(payload.remainingInMinorUnits)||Number(payload.remainingInMinorUnits)<0))throw new Error('تفصيل الدفعة غير مكتمل. أعد تحميل الوصل.');
  if(payload.paymentMethod==='exchange_credit'&&payload.exchange==null)throw new Error('تفصيل وصل التبديل غير متاح. أعد تحميل الرابط.');
  return {
    ...(payload.exchange!=null?{exchangeFunding:parseExchangeFunding(payload.exchange)}:{}),
    orderNumber: stringValue(payload.orderNumber),
    createdAt: stringValue(payload.createdAt),
    status: stringValue(payload.status),
    paymentMethod: stringValue(payload.paymentMethod),
    paymentStatus: stringValue(payload.paymentStatus),
    ...(hasInitial?{initialPaymentMethod:payload.initialPaymentMethod as 'cash'|'cliq',amountPaidInMinorUnits:Number(payload.amountPaidInMinorUnits),remainingInMinorUnits:Number(payload.remainingInMinorUnits)}:{}),
    subtotalInMinorUnits: integerValue(payload.subtotalInMinorUnits),
    discountInMinorUnits: integerValue(payload.discountInMinorUnits),
