      <Modal
        isOpen={currentModal === 'monitoring_dashboard'}
        onClose={closeModal}
        title="مراقبة صحة النظام"
        subtitle="حالة الخدمات والتكامل المالي والمخزني — للمالك فقط"
        maxWidth="max-w-4xl"
        maxHeight="max-h-[94vh]"
      >
        <MonitoringDashboardModal />
      </Modal>
    </>
  );
};

