      {replacement==='same'?<p className="text-sm">يخرج نفس الصنف والكمية بلا فرق سعر. يعود السليم فقط، ويُسجّل المعيب حسب قرارك.</p>:<>
        <p className="text-sm">لفواتير مسددة وطرد كامل أو باكيت بيع أصلي مستقل. لا دين جديد ولا تبديل نكهة كأنها الصنف نفسه.</p>
        <ProductPicker label="الصنف البديل" search={search} onSearch={setSearch} loading={productsLoading} disabled={locked} value={selectedProduct?.id}
          options={products.map(p=>({...productPickerOption(p,context.order.warehouseId),unit:'باكيت'}))} onChoose={id=>{const p=products.find(x=>x.id===id);if(!p)return;changed();setSelectedProduct(p);setReplacementKind(p.parcelOnly?'legacy_single_sku_parcel':'base_unit');}}/>
        {productsError&&<p role="alert" className="text-sm text-nw-bad">{productsError}</p>}
        {selectedProduct&&<><p className="font-semibold">البديل: {selectedProduct.nameAr}</p><label>طريقة بيع البديل<select aria-label="طريقة بيع البديل" value={replacementKind} onChange={e=>{changed();setReplacementKind(e.target.value as typeof replacementKind);}}>
          {!selectedProduct.parcelOnly&&<option value="base_unit">باكيت</option>}{(selectedProduct.unitsPerSalePackage??1)>1&&(selectedProduct.salePackagePrice??0)>0&&<option value="legacy_single_sku_parcel">طرد ({selectedProduct.unitsPerSalePackage} باكيت)</option>}</select></label>
          <label>عدد {replacementKind==='base_unit'?'الباكيتات':'الطرود'} البديلة<input type="number" min={1} step={1} inputMode="numeric" enterKeyHint="next" value={replacementQuantity} onChange={e=>{changed();setReplacementQuantity(Number(e.target.value));}}/></label></>}
        <label>كيف تسوّي فرق المال؟<select aria-label="كيف تسوّي فرق المال؟" value={differenceMethod??''} onChange={e=>{changed();setDifferenceMethod(e.target.value?(e.target.value as 'cash'|'cliq'):null);}}><option value="">اختر بعد المعاينة</option><option value="cash">كاش — داخل أو خارج الدرج</option><option value="cliq">CliQ — خارج الدرج</option></select></label>
      </>}</>}
      {(intent==='refund'&&(refundMethod==='cliq'||refundMethod==='auto'&&order.paymentMethod==='cliq')||intent==='replace'&&replacement==='other'&&differenceMethod==='cliq')&&<label>مرجع CliQ<input value={reference} maxLength={120} enterKeyHint="next" onChange={e=>{changed();setReference(e.target.value);}}/></label>}
      <details><summary className="min-h-11 cursor-pointer py-3">متقدم · السبب والملاحظة</summary><label>سبب العملية<input value={reason} maxLength={500} onChange={e=>{changed();setReason(e.target.value);}}/></label><label>ملاحظة<textarea rows={3} value={notes} onChange={e=>{changed();setNotes(e.target.value);}}/></label></details>
    </div>}
    {step===6&&preview&&<div className="space-y-3" data-testid="aftercare215-preview"><p>يرجع للمخزون <b>{preview.goodQuantity} باكيت</b> · معيب <b>{preview.badQuantity} باكيت</b>{preview.customerDamageQuantity>0&&` · يبقى للزبون ${preview.customerDamageQuantity} باكيت`}</p>
      {preview.badQuantity>0&&<p>{destination==='supplier'?'المعيب بانتظار المورد':'المعيب خسارة نهائية عليّ'}</p>}
      {preview.kind==='sealed_return'&&<><p>المبيعات −{formatExactMinorJod(preview.entitlementInMinorUnits)}</p><p>ينقص من دين هذه الفاتورة: {formatExactMinorJod(preview.debtReductionInMinorUnits)}</p>
        {BigInt(preview.moneyRefundInMinorUnits)>0n?<p>تعطي الزبون {formatExactMinorJod(preview.moneyRefundInMinorUnits)} {preview.refundMethod==='cash'?'كاش من الدرج':preview.refundMethod==='cliq'?'CliQ من حسابك':'— اختر طريقة الرد'}</p>:<p>بلا مصاري من الدرج أو الحساب.</p>}</>}
      {preview.kind==='inspected_replacement'&&<><p>خرج للزبون {preview.issuedQuantity} باكيت بنفس الصنف · فرق المال 0.000 د.أ</p><p>صافي المخزون: {preview.goodQuantity-preview.issuedQuantity} باكيت</p></>}
      {preview.kind==='exchange'&&<><p>البديل: {preview.productName} · {preview.baseQuantity} باكيت</p><p>مقابل داخلي من المرتجع: {formatExactMinorJod(preview.internalCreditInMinorUnits)}</p><p>إجمالي البديل: {formatExactMinorJod(preview.newTotalInMinorUnits)}</p>
        <p>{BigInt(preview.moneyReceivedInMinorUnits)>0n?`تقبض الآن ${formatExactMinorJod(preview.moneyReceivedInMinorUnits)}`:BigInt(preview.moneyRefundInMinorUnits)>0n?`تعطي الزبون ${formatExactMinorJod(preview.moneyRefundInMinorUnits)}`:'فرق المال: 0.000 د.أ'} {preview.differenceMethod==='cash'?'كاش من/إلى الدرج':preview.differenceMethod==='cliq'?'CliQ خارج الدرج':''}</p></>}
      {ownerAllowed&&preview.ownerValues&&<details><summary className="min-h-11 cursor-pointer py-3">قيم المالك</summary><dl className="space-y-2">{Object.entries(preview.ownerValues).map(([key,value])=><div key={key} className="flex flex-wrap justify-between gap-2"><dt>{privateLabels[key]??'قيمة العملية'}</dt><dd dir="ltr">{value.includes('.')?`${value.startsWith('-')?'−':''}${formatExactUnitCostJod(value.replace(/^-/u,''))}`:formatExactMinorJod(value)}</dd></div>)}</dl></details>}
      {preview.issues.length>0&&<div role="alert" className="space-y-2 text-sm text-nw-bad">{preview.issues.map((issue,index)=><p key={index}>{issue.field==='referenceNumber'?'مرجع CliQ':issue.field==='cashShift'?'الوردية':issue.field==='differenceMethod'?'طريقة فرق المال':'طريقة رد المال'}: {businessErrorMessage(issue.code)}</p>)}<p>ارجع للخطوة السابقة وأكمل الخانة المذكورة، ثم أعد المعاينة.</p></div>}
    </div>}
    </fieldset>
    <div className="flex flex-wrap gap-2">
      {step>1&&<UiButton disabled={busy} onClick={()=>{changed();setStep(step-1);}}>رجوع</UiButton>}
      {step<5&&<UiButton variant="primary" disabled={locked} onClick={next}>التالي</UiButton>}
      {(step===5||step===6&&!preview)&&<UiButton variant="primary" disabled={locked} onClick={()=>void requestPreview()}>{busy?'جاري المعاينة…':'معاينة التفاصيل'}</UiButton>}
      {step===6&&preview?.canConfirm&&<UiButton variant="primary" disabled={locked} onClick={()=>void confirm()}>{busy?'جارٍ التأكيد…':intent==='refund'?'تأكيد الإرجاع':'تأكيد الاستبدال'}</UiButton>}
    </div>
    {step===6&&!preview&&<p className="text-sm text-nw-muted">أعد معاينة التفاصيل بعد أي تعديل.</p>}
  </FormFields>;
}

src/features/orders/OrderDetailModal.tsx.beforeText:
import {newestRecords} from '../../utils/newestRecords';
import React, { useCallback, useState, useSyncExternalStore } from 'react';
import {
  AlertTriangle,
  Banknote,
  BookUser,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Clock3,
  Copy,
  MessageCircle,
  PackageCheck,
  Phone,
  Printer,
  ReceiptText,
  Share2,
  RotateCcw,
  Smartphone,
  Truck,
  X,
  XCircle,
} from 'lucide-react';
import { MoneyText, StatusBadge, UiButton, formatUiDate } from '../../components/ui';
import { getOrderStatus, PAYMENT_METHOD_LABELS } from './orderStatus';
import { OrderCommercialSummary } from './OrderCommercialSummary';
import { useDialogFocus } from '../../hooks/useDialogFocus';
import { CURRENCY } from '../../constants';
import { useAppStoreActions, useAppStoreSelector } from '../../stores/useAppStore';
import { Order, OrderStatus } from '../../types';
import { CustomerLocationCard } from './CustomerLocationCard';
import { EditAddressModal } from './EditAddressModal';
import { AdminAftercarePanel } from './AdminAftercarePanel';
import { buildStorefrontTrackingUrl } from '../../services/supabase/orders.service';
import type { AdminAftercareCapability } from '../../services/supabase/salesAftercare.service';
import {DocumentCorrectionAction} from '../corrections/DocumentCorrectionAction';
import {SaleReceiptDialog} from '../receipts/SaleReceiptDialog';
import {orderReceipt} from '../receipts/saleReceipt';
import {receiptDocumentShareText} from '../../../customer-web/src/receipts/commercialReceipt';

interface OrderDetailModalProps {
  order: Order;
  onClose: () => void;
  onOrderChanged?: () => Promise<void>;
  embedded?: boolean;
  historyContext?: boolean;
  onPrint?: () => void;
}

const STATUS_LABELS: Record<string, string> = {
  new: 'طلب جديد',
  confirmed: 'مؤكد',
  preparing: 'قيد التجهيز',
  processing: 'قيد التجهيز',
  ready: 'جاهز للتوصيل',
  out_for_delivery: 'خرج للتوصيل',
  delivered: 'مكتمل',
  completed: 'مكتمل',
  cancelled: 'ملغي',
  returned: 'مرتجع',
  expired: 'انتهت مهلة الحجز',
};



function nextOrderStep(status: OrderStatus) {
  if (status === 'confirmed') {
    return {
      status: 'preparing' as OrderStatus,
      label: 'بدء تجهيز الطلب',
      icon: PackageCheck,
      color: 'bg-nw-primary hover:bg-nw-primary',
    };
  }
  if (status === 'preparing' || status === 'processing') {
    return {
      status: 'out_for_delivery' as OrderStatus,
      label: 'بدء التوصيل',
      icon: Truck,
      color: 'bg-nw-primary hover:bg-nw-primary',
    };
  }
  if (status === 'ready') {
    return {
      status: 'out_for_delivery' as OrderStatus,
      label: 'خرج الطلب للتوصيل',
      icon: Truck,
      color: 'bg-nw-primary hover:bg-nw-primary',
    };
  }
  if (status === 'out_for_delivery') {
    return {
      status: 'delivered' as OrderStatus,
      label: 'تأكيد التسليم وخصم المخزون',
      icon: CheckCircle2,
      color: 'bg-nw-primary hover:bg-nw-primary',
    };
  }
  return null;
}

function normalizeJordanianPhone(value: string): string | null {
  const digits = value.replace(/\D/g, '');
  const local = digits.startsWith('962')
    ? `0${digits.slice(3)}`
    : digits.startsWith('0')
      ? digits
      : `0${digits}`;
  return /^07[789]\d{7}$/.test(local) ? local : null;
}

const subscribePhoneViewport = (notify: () => void) => {
  const query = window.matchMedia('(max-width: 767px)');
  query.addEventListener('change', notify);
  return () => query.removeEventListener('change', notify);
};
const isPhoneViewport = () => window.matchMedia('(max-width: 767px)').matches;

export const OrderDetailModal: React.FC<OrderDetailModalProps> = ({
  order,
  onClose,
  onOrderChanged,
  embedded = false,
  historyContext = false,
  onPrint,
}) => {
  const {
    confirmOrder,
    cancelOrder,
    advanceOrderStatus,
    startOrUpdateOrderDelivery,
    completeWebsiteOrderWithSettlement,
    openCustomerProfile,
    setToast,
  } = useAppStoreActions();

  const [busy, setBusy] = useState(false);
  const [showReceipt, setShowReceipt] = useState(false);
  const receiptBranch = useAppStoreSelector(state => state.branches.find(branch => branch.id === order.branchId));
  const receiptResult=(()=>{try{return {receipt:orderReceipt(order,receiptBranch),error:''};}
    catch(cause){return {receipt:null,error:cause instanceof Error?cause.message:'تعذر قراءة دليل الوصل.'};}})();
  const savedReceipt=receiptResult.receipt;
  const copyReceiptLink = async () => {
    if (!order.publicReceiptUrl) return;
    try {
      await navigator.clipboard.writeText(order.publicReceiptUrl);
      setToast('تم نسخ رابط الوصل.', 'success');
    } catch {
      setToast('تعذر نسخ رابط الوصل على هذا الجهاز.', 'error');
    }
  };
  const shareReceipt = async () => {
    if (!order.publicReceiptUrl||!savedReceipt) return;
    try {
      const text = receiptDocumentShareText(savedReceipt, order.publicReceiptUrl);
      if (navigator.share) await navigator.share({title:`وصل ${order.orderNumber}`, text, url:order.publicReceiptUrl});
      else {
        await navigator.clipboard.writeText(text);
        setToast('تم نسخ الوصل مع رابطه للمشاركة.', 'success');
      }
    } catch (error) {
      if (error instanceof DOMException && error.name === 'AbortError') return;
      setToast('تعذرت مشاركة الوصل على هذا الجهاز.', 'error');
    }
  };
  const [showCancelForm, setShowCancelForm] = useState(false);
  const [cancelReason, setCancelReason] = useState('');
  const [showEditAddress, setShowEditAddress] = useState(false);
  const [showPaymentConfirmation, setShowPaymentConfirmation] =
    useState(false);
  const [collectedBy, setCollectedBy] = useState<'cash' | 'cliq'>(
    order.paymentMethod === 'cliq' ? 'cliq' : 'cash'
  );
  const [settlementMode, setSettlementMode] = useState<
    'full' | 'partial' | 'debt'
  >('full');
  const [partialAmount, setPartialAmount] = useState('');
  const [deliveryFeeInput, setDeliveryFeeInput] = useState(
    String(order.deliveryFee || 0)
  );
  const [paymentReference, setPaymentReference] = useState('');
  const [paymentNotes, setPaymentNotes] = useState('');
  const [aftercareCapability, setAftercareCapability] =
    useState<AdminAftercareCapability | null>(null);
  const [showDeliveryEtaForm, setShowDeliveryEtaForm] = useState(false);
  const [deliveryEtaMinutes, setDeliveryEtaMinutes] = useState(30);
  const [deliveryDriverPhone, setDeliveryDriverPhone] = useState(
    order.deliveryDriverPhone || ''
  );
  const [latestTrackingUrl, setLatestTrackingUrl] = useState('');
  const nextStep = nextOrderStep(order.status);
  const phoneViewport = useSyncExternalStore(subscribePhoneViewport, isPhoneViewport, () => false);
  const fullScreenDetail = embedded && phoneViewport && !historyContext;
  const detailFocus = useDialogFocus(!embedded || fullScreenDetail, () => { if (!busy) onClose(); }, true);
  const handleAftercareContract = useCallback((capability: AdminAftercareCapability | null) => {
    setAftercareCapability(capability);
  }, []);
  const parsedDeliveryFee = Number(deliveryFeeInput);
  const settlementDeliveryFee = Number.isFinite(parsedDeliveryFee)
    ? parsedDeliveryFee
    : 0;
  const settlementTotal = Math.max(
    0,
    order.subtotal - order.discount + settlementDeliveryFee
  );
  const parsedPartialAmount = Number(partialAmount);
  const settlementCollectedAmount =
    settlementMode === 'full'
      ? settlementTotal
      : settlementMode === 'debt'
        ? 0
        : Number.isFinite(parsedPartialAmount)
          ? parsedPartialAmount
          : 0;
  const settlementRemaining = Math.max(
    0,
    settlementTotal - settlementCollectedAmount
  );
  const canCancel = ![
    'completed',
    'delivered',
    'cancelled',
    'returned',
  ].includes(
    order.status
  );

  const runAction = async (action: () => Promise<unknown>) => {
    setBusy(true);
    try {
      await action();
      await onOrderChanged?.();
    } finally {
      setBusy(false);
    }
  };

  const handleCancel = async () => {
    if (!cancelReason.trim()) {
      setToast('اكتب سبب إلغاء الطلب قبل المتابعة.', 'error');
      return;
    }
    await runAction(() => cancelOrder(order.id, cancelReason.trim()));
    setShowCancelForm(false);
  };

  const handleConfirmPaymentAndDelivery = async () => {
    if (!Number.isFinite(parsedDeliveryFee) || parsedDeliveryFee < 0) {
      setToast('أجرة التوصيل يجب أن تكون صفرًا أو أكثر.', 'error');
      return;
    }
    if (
      settlementMode === 'partial' &&
      (!Number.isFinite(parsedPartialAmount) ||
        parsedPartialAmount <= 0 ||
        parsedPartialAmount >= settlementTotal)
    ) {
      setToast(
        `الدفعة الجزئية يجب أن تكون أكبر من صفر وأقل من ${settlementTotal.toFixed(3)} ${CURRENCY}.`,
        'error'
      );
      return;
    }
    if (
      settlementMode !== 'debt' &&
      collectedBy === 'cliq' &&
      !paymentReference.trim()
    ) {
      setToast('اكتب رقم مرجع عملية CliQ قبل تأكيد القبض.', 'error');
      return;
    }

    setBusy(true);
    try {
      const success = await completeWebsiteOrderWithSettlement({
        orderId: order.id,
        paymentMethod:
          settlementMode === 'debt' ? 'debt' : collectedBy,
        amountCollected: settlementCollectedAmount,
        deliveryFee: settlementDeliveryFee,
        referenceNumber: paymentReference.trim(),
        notes: paymentNotes.trim(),
      });
      if (success) {
        setShowPaymentConfirmation(false);
        await onOrderChanged?.();
      }
    } finally {
      setBusy(false);
    }
  };

  const handleStartOrUpdateDelivery = async () => {
    if (!Number.isInteger(deliveryEtaMinutes) || deliveryEtaMinutes < 5 || deliveryEtaMinutes > 360) {
      setToast('وقت الوصول المتوقع يجب أن يكون بين 5 و360 دقيقة.', 'error');
      return;
    }

    const normalizedDriverPhone = normalizeJordanianPhone(
      deliveryDriverPhone
    );
    if (!normalizedDriverPhone) {
      setToast(
        'أدخل رقم سائق أردني صحيح، مثل 0791234567.',
        'error'
      );
      return;
    }

    setBusy(true);
    try {
      const result = await startOrUpdateOrderDelivery(
        order.id,
        deliveryEtaMinutes,
        normalizedDriverPhone
      );
      if (result.success) {
        setLatestTrackingUrl(result.trackingUrl || '');
        setDeliveryDriverPhone(
          result.driverPhone || normalizedDriverPhone
        );
        setShowDeliveryEtaForm(false);
        await onOrderChanged?.();
      }
    } finally {
      setBusy(false);
    }
  };

  const copyTrackingLink = async () => {
    const trackingUrl =
      latestTrackingUrl ||
      (order.trackingToken
        ? buildStorefrontTrackingUrl(order.trackingToken)
        : '');
    if (!trackingUrl) {
      setToast('رابط التتبع غير متاح لهذا الطلب بعد.', 'error');
      return;
    }

    try {
      await navigator.clipboard.writeText(trackingUrl);
      setToast('تم نسخ رابط تتبع الطلب لإرساله إلى العميل.');
    } catch {
      setToast('تعذر نسخ الرابط على هذا الجهاز.', 'error');
    }
  };


  const phoneDigits = order.customerPhone.replace(/\D/g, '');
  const whatsappPhone = phoneDigits.startsWith('962')
    ? phoneDigits
    : phoneDigits.startsWith('0')
    ? `962${phoneDigits.slice(1)}`
    : `962${phoneDigits}`;
  const currentTrackingUrl =
    latestTrackingUrl ||
    (order.trackingToken
      ? buildStorefrontTrackingUrl(order.trackingToken)
      : '');
  const currentDriverPhone =
    order.deliveryDriverPhone || deliveryDriverPhone;
  const normalizedDriverPhone = normalizeJordanianPhone(currentDriverPhone);
  const trackingMessage = currentTrackingUrl
    ? [
        `مرحبًا ${order.customerName}،`,
        `طلبك رقم ${order.orderNumber} خرج للتوصيل.`,
        order.estimatedArrivalAt
          ? `وقت الوصول المتوقع: ${new Date(
              order.estimatedArrivalAt
            ).toLocaleTimeString('ar-JO-u-nu-latn', {
              hour: '2-digit',
              minute: '2-digit',
            })}`
          : '',
        normalizedDriverPhone
          ? `رقم السائق: ${normalizedDriverPhone}`
          : '',
        `تابع حالة الطلب من هنا: ${currentTrackingUrl}`,
      ]
        .filter(Boolean)
        .join('\n')
    : '';
  const trackingWhatsAppUrl =
    whatsappPhone && trackingMessage
      ? `https://wa.me/${whatsappPhone}?text=${encodeURIComponent(
          trackingMessage
        )}`
      : '';
  const focusActionArea = (openAction: () => void) => {
    openAction();
    window.requestAnimationFrame(() => {
      document
        .getElementById(`order-action-area-${order.id}`)
        ?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  };

  return (
    <div ref={detailFocus as React.RefObject<HTMLDivElement>} role={!embedded || fullScreenDetail ? 'dialog' : undefined} aria-modal={!embedded || fullScreenDetail ? true : undefined} aria-label={`تفاصيل الطلب ${order.orderNumber}`} aria-busy={busy} className="order-detail space-y-4 break-words text-sm text-nw-text">
      {embedded && <header className="sticky top-0 z-10 -mx-4 -mt-4 border-b border-nw-border bg-nw-bg p-4 pt-[max(1rem,env(safe-area-inset-top))] md:hidden">
        <UiButton aria-label={historyContext ? "إغلاق الفاتورة" : "رجوع للطلبات"} onClick={onClose} disabled={busy}><ChevronRight className="h-4 w-4" />{historyContext ? "إغلاق الفاتورة" : "رجوع للطلبات"}</UiButton>
      </header>}
      <div className="flex items-start justify-between border-b border-nw-border pb-3">
        <div className="md:min-w-0 md:flex-1">
          <bdi dir="ltr" className="select-text font-mono text-[11px] font-black text-nw-info">
            {order.orderNumber}
          </bdi>
          <h3 className="text-sm font-black text-nw-text">{order.customerName}</h3>
          <span className="text-[10px] text-nw-muted">
            {formatUiDate(order.createdAt, { dateStyle: 'medium', timeStyle: 'short' })}
          </span>
        </div>
        <div className="flex min-w-0 flex-wrap items-center gap-2">
          <StatusBadge tone={getOrderStatus(order.status).tone}>{STATUS_LABELS[order.status] || order.status}</StatusBadge>
          <UiButton
            type="button"
            onClick={onClose}
            disabled={busy} className="min-h-11 min-w-11 rounded-full bg-nw-surface-2 p-2 text-nw-muted"
            aria-label="إغلاق"
          >
            <X className="h-4 w-4" />
          </UiButton>
        </div>
      </div>

      <bdi dir="ltr" className="block text-xs text-nw-muted">{order.customerPhone || 'لا يوجد رقم هاتف'}</bdi>
      <p className="text-xs text-nw-muted">{order.governorate} · {order.region} · {order.address}</p>
      <div className="flex flex-wrap gap-2 print:hidden" aria-label="وصل الشراء">
        <UiButton variant="primary" disabled={!savedReceipt} onClick={() => setShowReceipt(true)}><Printer className="h-4 w-4" />طباعة الوصل</UiButton>
        {receiptResult.error&&<p role="alert" className="w-full text-sm text-nw-bad">{receiptResult.error}</p>}
        {order.publicReceiptUrl && <>
          <UiButton disabled={!savedReceipt} onClick={() => void shareReceipt()}><Share2 className="h-4 w-4" />مشاركة الوصل</UiButton>
