  const [isProductsLoading, setIsProductsLoading] = useState(true);
  const [productsError, setProductsError] = useState<string | null>(null);
  const [cartItems, setCartItems] = useState<PosCartItem[]>([]);
  const [selectedWarehouseId, setSelectedWarehouseId] = useState('');
  const branchWarehouses = warehouses.filter(w => w.branchId === activeBranch.id);
  const warehouseId = branchWarehouses.find(w => w.id === selectedWarehouseId)?.id
    || (branchWarehouses.length === 1 ? branchWarehouses[0].id : '');
  const [parcelOptions, setParcelOptions] = useState<PosParcelOption[]>([]);
  const [parcelOption, setParcelOption] = useState<PosParcelOption | null>(null);
  const [editingParcelId, setEditingParcelId] = useState<string | null>(null);
  const [recoveryStatus, setRecoveryStatus] = useState<string | null>(null);
  const [absenceState, setAbsenceState] = useState<'ABSENT' | 'EXISTS' | 'CANCELLED_UNCOMMITTED' | null>(null);
  const [cancelConfirmed, setCancelConfirmed] = useState(false);
  const recoveryBlocked = recoveryStatus !== null && !['SUCCEEDED', 'DEFINITIVELY_REJECTED', 'CANCELLED_UNCOMMITTED'].includes(recoveryStatus);
  const [posCustomers, setPosCustomers] = useState<PosCustomer[]>([]);
  const [customerSearch, setCustomerSearch] = useState('');
  const [posCustomerPage, setPosCustomerPage] = useState(1);
  const [posCustomerTotal, setPosCustomerTotal] = useState(0);
  const [posCustomersHaveMore, setPosCustomersHaveMore] = useState(false);
  const [isPosCustomersLoading, setIsPosCustomersLoading] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string>('');
  const [discountAmount, setDiscountAmount] = useState<number>(0);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>('cash');
  const [cashReceived, setCashReceived] = useState<number>(0);
  const [initialPaidText,setInitialPaidText]=useState('');
  const [initialPaidMethod,setInitialPaidMethod]=useState<'cash'|'cliq'>('cash');
  const [initialPaidReference,setInitialPaidReference]=useState('');
  const [showReceiptModal, setShowReceiptModal] = useState<boolean>(false);
  const [lastInvoice, setLastInvoice] = useState<
    (Invoice & { changeDue: number }) | null
  >(null);
  useEffect(() => { if (showReceiptModal) setIsCartOpen(false); }, [showReceiptModal]);
  const [isBarcodeScannerOpen, setIsBarcodeScannerOpen] = useState<boolean>(false);
  const [isAddCustomerOpen, setIsAddCustomerOpen] = useState<boolean>(false);
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const [openPosShift, setOpenPosShift] = useState<OpenPosShift | null>(null);
  const [isShiftStatusLoading, setIsShiftStatusLoading] = useState(true);
  useScreenLeaveGuard('pos', () => {
    if (isSubmitting) {setToast('البيع قيد الإرسال. انتظر النتيجة قبل الرجوع.', 'info'); return false;}
    if (recoveryBlocked) {setToast(operatorErrorMessage('saleUnknown'), 'error'); return false;}
    return cartItems.length === 0 || window.confirm('السلة غير محفوظة. هل تريد مغادرة نقطة البيع وإفراغ السلة؟');
  });
  const knownProductsRef = useRef<Map<string, Product>>(new Map());
  const cartWarehouseRef = useRef<string>('');
  const searchInputRef = useRef<HTMLInputElement>(null);

  const refreshRecovery = () => {
    setAbsenceState(null); setCancelConfirmed(false);
    try {setRecoveryStatus(readPosV2Recovery(currentUser.id)?.status || null);}
    catch {setRecoveryStatus('UNPROVEN');}
  };
  useEffect(() => {
    const refresh = () => {
      setAbsenceState(null); setCancelConfirmed(false);
      try {setRecoveryStatus(readPosV2Recovery(currentUser.id)?.status || null);}
      catch {setRecoveryStatus('UNPROVEN');}
    };
    refresh(); window.addEventListener('storage', refresh);
    return () => window.removeEventListener('storage', refresh);
  }, [currentUser.id]);
  useEffect(() => {
    let active = true; setParcelOptions([]); setParcelOption(null);
    if (warehouseId && supabase) void Promise.resolve(supabase.rpc('get_pos_configurable_parcel_options_v1', {p_warehouse_id: warehouseId}))
      .then(({data, error}) => {
        if (!active) return;
        if (error || !data || !Array.isArray(data.options)) {setToast('تعذر قراءة إعداد طرود الكاشير.', 'error'); return;}
        const options = data.options as PosParcelOption[];
        if (options.some(o => !o.familyProductId || !o.parcelConfigurationId || !Number.isSafeInteger(o.configurationRevision)
          || o.configurationRevision < 1 || !Number.isSafeInteger(o.unitsPerParcel) || o.unitsPerParcel < 1
          || !Number.isSafeInteger(o.parcelPriceInMinorUnits) || o.parcelPriceInMinorUnits < 1 || !Array.isArray(o.components)
          || !o.components.length || new Set(o.components.map(c => c.productId)).size !== o.components.length
          || o.components.some(c => !c.productId || typeof c.nameAr !== 'string'
            || !Number.isSafeInteger(c.availableQuantity) || c.availableQuantity < 0))) {
          setToast('بيانات الطرود غير مكتملة؛ أعد تحميلها.', 'error'); return;
        }
        setParcelOptions(options);
      }).catch(() => {if (active) setToast('تعذر تحميل طرود الكاشير. تحقق من الاتصال.', 'error');});
    return () => {active = false;};
  }, [warehouseId, productDataRevision, setToast]);

  const cartFits = (next: PosCartItem[]) => [...posStockDemand(next)].every(([id, quantity]) => {
    const product = knownProductsRef.current.get(id);
    const component = parcelOptions.flatMap(p => p.components).find(c => c.productId === id);
    const available = product ? posWarehouseAvailable(product, warehouseId) : component?.availableQuantity;
    return Number.isSafeInteger(quantity) && quantity > 0 && available !== undefined && quantity <= available;
  });

  useEffect(() => {
    let active = true;
    const timer = window.setTimeout(() => {
      setIsProductsLoading(true);
      setProductsError(null);
      searchAdminProducts({
        search: searchQuery,
        limit: 40,
        categoryId: selectedCategory === 'all' ? undefined : selectedCategory,
        purpose: 'sellable',
      })
        .then((result) => {
          if (!active) return;
          const sellableProducts = result.filter(isPosSellableProduct);
          sellableProducts.forEach((product) =>
            knownProductsRef.current.set(product.id, product),
          );
          setPosProducts(sellableProducts);
          cacheProductPage(sellableProducts);
        })
        .catch(() => {
          if (!active) return;
          setProductsError(
            operatorErrorMessage('products'),
          );
          setPosProducts([]);
        })
        .finally(() => {
          if (active) setIsProductsLoading(false);
        });
    }, searchQuery.trim() ? 250 : 0);

    return () => {
      active = false;
      window.clearTimeout(timer);
    };
  }, [cacheProductPage, productDataRevision, searchQuery, selectedCategory]);

  useEffect(() => {
    let active = true;
    const timer = window.setTimeout(() => {
      setIsPosCustomersLoading(true);
      fetchPosCustomersFromSupabase({
        page: 1,
        pageSize: 25,
        search: customerSearch,
      })
        .then((result) => {
          if (!active) return;
          setPosCustomers((currentCustomers) => {
            const selected = currentCustomers.find(
              (customer) => customer.id === selectedCustomerId
            );
            if (
              selected &&
              !result.customers.some((customer) => customer.id === selected.id)
            ) {
              return [selected, ...result.customers];
            }
            return result.customers;
          });
          setPosCustomerPage(result.page);
          setPosCustomerTotal(result.totalCount);
          setPosCustomersHaveMore(result.hasMore);
        })
        .catch((error) => {
          if (!active) return;
          console.error('Unable to load POS customers:', error);
          setPosCustomers((currentCustomers) =>
            currentCustomers.filter(
              (customer) => customer.id === selectedCustomerId
            )
          );
          setPosCustomerTotal(0);
          setPosCustomersHaveMore(false);
        })
        .finally(() => {
          if (active) setIsPosCustomersLoading(false);
        });
    }, customerSearch.trim() ? 250 : 0);

    return () => {
      active = false;
      window.clearTimeout(timer);
    };
  }, [customerSearch, selectedCustomerId]);

  useEffect(() => {
    if (!activeBranch.id) return;
    let isMounted = true;
    setIsShiftStatusLoading(true);
    fetchOpenPosShiftFromSupabase(activeBranch.id)
      .then((shift) => {
        if (isMounted) setOpenPosShift(shift);
      })
      .catch((error) => {
        console.error('Unable to load POS shift status:', error);
        if (isMounted) setOpenPosShift(null);
      })
      .finally(() => {
        if (isMounted) setIsShiftStatusLoading(false);
      });

    return () => {
      isMounted = false;
    };
  }, [activeBranch.id]);

  const filteredProducts = posProducts;

  const resolveScannedProductCode = async (
    code: string,
  ): Promise<PosProductLookupResult> => {
    const matches = await searchAdminProducts({
      search: code,
      limit: 3,
      purpose: 'any',
    });
    matches.forEach((product) => knownProductsRef.current.set(product.id, product));
    return resolvePosProductCode(matches, code);
  };

  const restoreSearchFocus=(source:PosAdditionSource)=>{
    if(shouldRestorePosSearchFocus(source,{coarse:window.matchMedia('(pointer: coarse)').matches,
      touchPoints:navigator.maxTouchPoints??0,width:window.innerWidth}))searchInputRef.current?.focus({preventScroll: true});
    else searchInputRef.current?.blur();
  };
  const addToCart = (prod: Product,preferred:PosSingleProductMode='legacy_single_sku_parcel',source:PosAdditionSource='pointer') => {
    const productSaleMode=posSaleModeForProduct(prod,preferred);
    if (isSubmitting || recoveryBlocked || !warehouseId) {setToast('حدد المستودع واسترجع أي محاولة معلقة قبل البيع.', 'error'); return;}
    if (cartItems.length && cartWarehouseRef.current !== warehouseId) {setToast('تغير مستودع البيع؛ أفرغ السلة ثم أعد تركيبها.', 'error'); return;}
    cartWarehouseRef.current = warehouseId;
    knownProductsRef.current.set(prod.id, prod);
    const unitsPerSalePackage = productSaleMode === 'base_unit' ? 1 : Math.max(
      1,
      Math.floor(prod.unitsPerSalePackage || 1)
    );
    const availableSalePackages = calculateAvailableSalePackages(
      posWarehouseAvailable(prod, warehouseId),
      unitsPerSalePackage
    );
    const existingIndex = cartItems.findIndex((item) => item.productId === prod.id && item.v2Line.commercial_line_kind === productSaleMode);
    const currentQuantity =
      existingIndex >= 0 ? cartItems[existingIndex].quantity : 0;
    if (!canSetPosQuantity(currentQuantity + 1, availableSalePackages)) {
      setToast(`المتاح من ${prod.nameAr} هو ${availableSalePackages} ${productSaleMode==='base_unit'?'باكيت':'طرد'} فقط.`, 'error');
      return;
    }

    if (existingIndex >= 0) {
      const updated = cartItems.map(item => ({...item}));
      updated[existingIndex].quantity += 1;
      updated[existingIndex].baseQuantity = updated[existingIndex].quantity * unitsPerSalePackage;
      updated[existingIndex].totalPrice = updated[existingIndex].quantity * updated[existingIndex].unitPrice;
      if (!cartFits(updated)) {setToast('الكمية المشتركة للقطع والطرود تتجاوز مخزون المستودع.', 'error'); return;}
      setCartItems(updated);
    } else {
      const unitPrice = productSaleMode === 'base_unit' ? prod.retailPrice : prod.salePackagePrice;
      if (typeof unitPrice !== 'number' || !Number.isFinite(unitPrice) || unitPrice < 0) {setToast('سعر البيع غير متوفر.', 'error'); return;}
      const newItem: PosCartItem = {
        v2Line: productSaleMode === 'base_unit' ? {commercial_line_kind: productSaleMode, product_id: prod.id, base_quantity: 1}
          : {commercial_line_kind: productSaleMode, product_id: prod.id, parcel_quantity: 1, units_per_parcel: unitsPerSalePackage},
        id: `cart-${Date.now()}-${Math.random()}`,
        productId: prod.id,
        productName: prod.nameAr,
        productImage: prod.imageUrl,
        sku: prod.sku,
        unit: productSaleMode === 'base_unit' ? prod.unit : 'طرد',
        unitPrice,
        costPrice: prod.costPrice,
        quantity: 1,
        baseQuantity: unitsPerSalePackage,
        unitsPerSalePackage,
        salePackage: prod.salePackage || 'طرد',
        discount: 0,
        totalPrice: unitPrice,
      };
      if (!cartFits([...cartItems, newItem])) {setToast('الكمية المشتركة تتجاوز مخزون المستودع.', 'error'); return;}
      setCartItems([...cartItems, newItem]);
    }
    restoreSearchFocus(source);
  };

  const updateQuantity = (itemId: string, delta: number) => {
    if (isSubmitting || recoveryBlocked) return;
    const updated = cartItems
      .map((item) => {
        if (item.id === itemId) {
          const newQty = item.quantity + delta;
          if (newQty <= 0) return null;
          if (item.v2Line.commercial_line_kind === 'configurable_parcel') return item;
          const product = knownProductsRef.current.get(item.productId);
          const availableSalePackages = product
            ? calculateAvailableSalePackages(
                posWarehouseAvailable(product, warehouseId),
                item.unitsPerSalePackage || 1
              )
            : 0;
          if (
            product &&
            !canSetPosQuantity(newQty, availableSalePackages)
          ) {
            setToast(
              `المتاح من ${product.nameAr} هو ${availableSalePackages} طرد بيع فقط.`,
              'error'
            );
            return item;
          }
          return {
            ...item,
            quantity: newQty,
            baseQuantity:
              newQty * (item.unitsPerSalePackage || 1),
            totalPrice: newQty * item.unitPrice,
          };
        }
        return item;
      })
      .filter(Boolean) as PosCartItem[];

    if (!cartFits(updated)) {setToast('الكمية المشتركة تتجاوز مخزون المستودع.', 'error'); return;}
    setCartItems(updated);
  };

  const addParcel = (line: PosV2ConfigurableParcelLine) => {
    if (!parcelOption || recoveryBlocked || isSubmitting) return;
    const option = parcelOption;
    const item: PosCartItem = {id: crypto.randomUUID(), productId: option.familyProductId,
      productName: option.nameAr + ' — ' + line.parcel_instances[0].components.map(c =>
        `${option.components.find(p => p.productId === c.product_id)?.flavorNameAr || option.components.find(p => p.productId === c.product_id)?.nameAr}: ${c.base_quantity}`).join('، '),
      productImage: '', sku: '', unit: 'طرد مرن', unitPrice: option.parcelPriceInMinorUnits / 1000,
      costPrice: 0, quantity: 1, baseQuantity: option.unitsPerParcel, unitsPerSalePackage: option.unitsPerParcel,
      salePackage: 'طرد مرن', discount: 0, totalPrice: option.parcelPriceInMinorUnits / 1000, v2Line: line};
    if (cartItems.length && cartWarehouseRef.current !== warehouseId) {setToast('تغير مستودع البيع؛ أعد تركيب السلة.', 'error'); return;}
    const next = editingParcelId ? cartItems.map(c => c.id === editingParcelId ? {...item, id: c.id} : c) : [...cartItems, item];
    if (!cartFits(next)) {setToast('مكونات السلة تتجاوز المخزون المتاح.', 'error'); return;}
    cartWarehouseRef.current = warehouseId;
    setCartItems(next); setParcelOption(null); setEditingParcelId(null); restoreSearchFocus('pointer');
  };

  const posSummary = calculatePosSummary(
    cartItems,
    discountAmount,
    cashReceived
  );
  const subtotal = posSummary.subtotal;
  const totalAmount = posSummary.total;
  const changeDue = posSummary.changeDue;

  const handleCompleteSale = async () => {
    if (isSubmitting || recoveryBlocked || !warehouseId) return;
    if (cartItems.length === 0) return;
    const methodConflict=posCartSaleMethodConflict(cartItems,knownProductsRef.current);
    if(methodConflict){setToast(methodConflict,'error');return;}
    if (cartWarehouseRef.current !== warehouseId || !cartFits(cartItems)) {setToast('تغير المستودع أو المخزون المتاح؛ راجع السلة قبل الإرسال.', 'error'); return;}

    if (!openPosShift) {
      setToast('افتح وردية الصندوق أولاً قبل إتمام البيع المباشر.', 'error');
      return;
    }

    if (discountAmount > subtotal) {
      setToast('خصم الفاتورة لا يمكن أن يتجاوز مجموع الأصناف.', 'error');
      return;
    }
    if (
      paymentMethod === 'cash' &&
      cashReceived > 0 &&
      cashReceived < totalAmount
    ) {
      setToast('المبلغ المستلم أقل من إجمالي الفاتورة.', 'error');
      return;
    }
    if (paymentMethod === 'debt' && !selectedCustomerId) {
      setToast(
        'البيع الآجل يتطلب اختيار عميل مسجل حتى يُحفظ الدين على حسابه.',
        'error'
      );
      return;
    }

    const selectedCustomer = posCustomers.find(
      (customer) => customer.id === selectedCustomerId
    );
    let resolvedMethod=paymentMethod;
    let initialPayment:CreatePosSaleV2Input['initialPayment'];
    if(paymentMethod==='debt'){
      try{
        const paid=initialPaymentText216(initialPaidText);
        // Preserve existing fully-discounted/zero-total debt sales. They do
        // not enter the positive partial-payment contract.
        if(jodToMinorUnits(totalAmount)>0){
          const split=partialPayment216(jodToMinorUnits(totalAmount),paid,initialPaidMethod,selectedCustomer?.id??null);
          resolvedMethod=split.paymentMethod;
          if(split.initialPaymentMethod)initialPayment={amountInMinorUnits:split.paidInMinorUnits,method:split.initialPaymentMethod,referenceNumber:initialPaidReference.trim()||undefined};
        }else if(paid!==0)throw new Error('لا يمكن تسجيل دفعة لفاتورة صافيها صفر.');
      }catch(cause){setToast(operatorErrorMessage('partial',cause),'error');return;}
    }
    const request: CreatePosSaleV2Input = {warehouseId, branchId: activeBranch.id,
      customerId: selectedCustomer?.id, customerName: selectedCustomer?.name || 'زبون نقدي', paymentMethod:resolvedMethod,
      lines: posCartLines(cartItems), discountInMinorUnits: jodToMinorUnits(discountAmount),
      amountReceivedInMinorUnits: jodToMinorUnits(resolvedMethod === 'debt' ? 0
        : paymentMethod === 'debt' ? totalAmount : resolvedMethod === 'cash' ? cashReceived || totalAmount : totalAmount),
      ...(initialPayment?{initialPayment}:{}),idempotencyKey: crypto.randomUUID()};
    await executeSale('START_NEW', request);
  };

  const executeSale = async (intent: 'START_NEW' | 'RECOVER_EXISTING', request?: CreatePosSaleV2Input) => {
    if (!supabase || isSubmitting) return;
    setIsSubmitting(true);
    try {
      const result = await runPosV2Attempt(supabase, currentUser.id, intent, request);
      if (result.ok === false) {setToast(result.status === 'unknown' ? operatorErrorMessage('saleUnknown') : operatorPosRejectionMessage(result.errorIdentity), 'error'); return;}
      const meta = await supabase.from('orders').select('created_at,order_items(id,base_unit_name_snapshot)').eq('id', result.data.orderId).single();
      const invoice = posV2Invoice(result.data, currentUser, typeof meta.data?.created_at === 'string' ? meta.data.created_at : '',receiptBaseUnitNames(meta.data));
      try {invoice.publicReceiptUrl = await getOrCreatePublicPosReceiptUrlFromSupabase(result.data.orderId);} catch {/* Committed sale is still recoverable. */}
      setLastInvoice(invoice); setShowReceiptModal(true); setCartItems([]); setDiscountAmount(0);
      setCashReceived(0); setSelectedCustomerId(''); setPaymentMethod('cash');
      setInitialPaidText('');setInitialPaidMethod('cash');setInitialPaidReference('');
      await Promise.allSettled([refreshProductsFromSupabase(), refreshOrdersFromSupabase(),
        refreshInventoryMovementsFromSupabase(), refreshStockNotificationsFromSupabase()]);
      setToast(`تم حفظ البيع V2: ${result.data.orderNumber}`);
    } catch {setToast(operatorErrorMessage('saleUnknown'), 'error');}
    finally {setIsSubmitting(false); refreshRecovery();}
  };

  const handleCustomerCreated = (customer: CreatedCustomer) => {
    setPosCustomers((currentCustomers) => [
      ...currentCustomers.filter((item) => item.id !== customer.id),
      customer,
    ].sort((first, second) => first.name.localeCompare(second.name, 'ar')));
    setPosCustomerTotal((currentTotal) => currentTotal + 1);
    setSelectedCustomerId(customer.id);
  };

  const loadMorePosCustomers = async () => {
    if (!posCustomersHaveMore || isPosCustomersLoading) return;
    setIsPosCustomersLoading(true);
    try {
      const result = await fetchPosCustomersFromSupabase({
        page: posCustomerPage + 1,
        pageSize: 25,
        search: customerSearch,
      });
      setPosCustomers((currentCustomers) => {
        const existingIds = new Set(
          currentCustomers.map((customer) => customer.id)
        );
        return [
          ...currentCustomers,
          ...result.customers.filter(
            (customer) => !existingIds.has(customer.id)
          ),
        ];
      });
      setPosCustomerPage(result.page);
      setPosCustomerTotal(result.totalCount);
      setPosCustomersHaveMore(result.hasMore);
    } catch (error) {
      console.error('Unable to load more POS customers:', error);
      setToast('تعذر تحميل المزيد من العملاء.', 'error');
    } finally {
      setIsPosCustomersLoading(false);
    }
  };

  const selectedPosCustomer = posCustomers.find(
    (customer) => customer.id === selectedCustomerId
  );
  const receiptBranch = lastInvoice ? branches.find(branch => branch.id === lastInvoice.branchId) : undefined;


  const ensurePublicReceiptUrl = async () => {
    if (!lastInvoice) throw new Error('لا توجد فاتورة لإنشاء الرابط.');
    if (lastInvoice.publicReceiptUrl) return lastInvoice.publicReceiptUrl;

    const publicReceiptUrl =
      await getOrCreatePublicPosReceiptUrlFromSupabase(lastInvoice.id);
    setLastInvoice((current) =>
      current ? { ...current, publicReceiptUrl } : current
    );
    return publicReceiptUrl;
  };

  const handleShareReceipt = async () => {
    if (!lastInvoice) return;

    let publicReceiptUrl: string;
    try {
      publicReceiptUrl = await ensurePublicReceiptUrl();
    } catch {
      setToast(
        operatorErrorMessage('receipt'),
        'error'
      );
      return;
    }

    const text = buildReceiptShareText({
      businessName: 'النواصرة لتجارة الجملة والمواد الغذائية',
      branchName: receiptBranch?.name || lastInvoice.branchId,
      invoiceNumber: lastInvoice.invoiceNumber,
      customerName: lastInvoice.customerName,
      createdAt: lastInvoice.createdAt,
      items: lastInvoice.items,
      subtotal: lastInvoice.subtotal,
      discount: lastInvoice.discount,
      totalAmount: lastInvoice.totalAmount,
      paymentMethod: lastInvoice.paymentMethod,
      paidAmount: lastInvoice.paidAmount,
      initialPaymentMethod:lastInvoice.initialPaymentMethod,
      remainingAmount: lastInvoice.remainingAmount,
      changeDue: lastInvoice.changeDue,
      publicReceiptUrl,
    });

    try {
      if (navigator.share) {
        await navigator.share({
          title: `إيصال ${lastInvoice.invoiceNumber}`,
          text,
          url: publicReceiptUrl,
        });
        return;
      }

      window.open(
        `https://api.whatsapp.com/send/?text=${encodeURIComponent(text)}&type=custom_url&app_absent=0`,
        '_blank',
        'noopener,noreferrer'
      );
    } catch (shareError) {
      if (shareError instanceof DOMException && shareError.name === 'AbortError') {
        return;
      }
      setToast('تعذرت مشاركة الإيصال على هذا الجهاز.', 'error');
    }
  };

  const handleCopyReceiptLink = async () => {
    try {
      const publicReceiptUrl = await ensurePublicReceiptUrl();
      await navigator.clipboard.writeText(publicReceiptUrl);
      setToast('تم نسخ رابط الإيصال الإلكتروني.', 'success');
    } catch {
      setToast(
        operatorErrorMessage('receipt'),
        'error'
      );
    }
  };


  const cartMethodConflict=recoveryBlocked?null:posCartSaleMethodConflict(cartItems,knownProductsRef.current);
  const cartBaseUnitTotals=Array.from(cartItems.reduce((totals,item)=>{
    const name='باكيت';
    totals.set(name,(totals.get(name)??0)+item.baseQuantity);
    return totals;
  },new Map<string,number>()));
  let initialPaidIssue:string|null=null;let initialDue:number|null=null;
  if(paymentMethod==='debt')try{
    const paid=initialPaymentText216(initialPaidText),due=jodToMinorUnits(totalAmount)-paid;
    if(due<0)throw new Error('المدفوع الآن أكبر من صافي الفاتورة.');initialDue=due/1000;
  }catch(cause){initialPaidIssue=operatorErrorMessage('partial',cause);}
  const paymentControl = <fieldset disabled={isSubmitting||recoveryBlocked}><SegmentedControl touchSize label="طريقة الدفع" value={paymentMethod}
 options={[{value: 'cash' as PaymentMethod, label: 'كاش'}, {value: 'cliq' as PaymentMethod, label: 'CliQ'}, {value: 'debt' as PaymentMethod, label: 'دين / دفع جزئي'}]}
 onChange={value => {setPaymentMethod(value);if(value==='debt')setIsCartOpen(true);}} /></fieldset>;
  const completeSaleButton = (            <UiButton data-testid="pos-complete-sale" variant="accent" size="large"
              onClick={() =>
                openPosShift
                  ? void handleCompleteSale()
                  : setActiveTab('shifts')
              }
              disabled={
                cartItems.length === 0 ||
                isSubmitting ||
                recoveryBlocked || !warehouseId ||
                isShiftStatusLoading
              }
              className="w-full min-w-0 whitespace-nowrap px-2 text-xs sm:text-sm"
            >
              {isSubmitting ? (
                <Loader2 className="w-4 h-4 animate-spin" />
              ) : (
                <Receipt className="w-4 h-4" />
              )}
              <span>
                {isSubmitting
                  ? 'جاري حفظ البيع...'
                  : openPosShift
                  ? 'إتمام البيع · ' + totalAmount.toFixed(3)
                  : 'فتح وردية للمتابعة'}
              </span>
            </UiButton>
);
  const cartTotals = <div className="flex flex-wrap items-center justify-between gap-2">
    <span className="text-xs text-nw-muted">{formatItemCount(cartItems.length)} · <bdi dir="ltr">{cartItems.reduce((sum, item) => sum + item.quantity, 0)}</bdi> وحدات بيع</span>
    <span data-testid="pos-cart-base-units" className="text-xs text-nw-muted">{cartBaseUnitTotals.length?cartBaseUnitTotals.map(([name,quantity],index)=><React.Fragment key={name}>{index>0?'، ':''}<bdi dir="ltr">{quantity}</bdi> {name}</React.Fragment>):'0 باكيت'}</span>
    <strong className="w-full text-2xl"><MoneyText amount={totalAmount} currency /></strong>
  </div>;

  return (
    <div dir="rtl" data-testid="pos-workbench" className="min-w-0 bg-nw-bg text-nw-text">
      <PageHeader title="نقطة البيع" actions={<>
        <StatusBadge tone={isShiftStatusLoading ? 'mute' : openPosShift ? 'ok' : 'warn'}>
          {isShiftStatusLoading ? 'جاري التحقق من الوردية' : openPosShift ? 'الوردية مفتوحة' : 'لا توجد وردية مفتوحة'} · {currentUser.name}
        </StatusBadge>
      </>} />
      <div className="space-y-4 p-4 pb-64 sm:p-6 sm:pb-64 lg:pb-6">
        {!isShiftStatusLoading && !openPosShift && <Card role="status" className="flex flex-wrap items-center justify-between gap-3">
          <div><strong className="block text-sm text-nw-warn">البيع المباشر متوقف مؤقتًا</strong><p className="m-0 text-sm text-nw-muted">افتح وردية الصندوق حتى تُربط الفاتورة والحسابات بها تلقائيًا.</p></div>
          <UiButton onClick={() => setActiveTab('shifts')}>فتح وردية</UiButton>
        </Card>}
              {recoveryStatus && recoveryStatus !== 'DEFINITIVELY_REJECTED' && <div className="rounded-xl border border-nw-warn p-3 text-xs" role="status">
        <p>{recoveryStatus === 'CANCELLED_UNCOMMITTED' ? 'ألغيت المحاولة بعد إثبات الخادم عدم تسجيلها. يمكنك بدء بيع جديد.'
          : recoveryBlocked ? operatorErrorMessage('saleUnknown') : 'آخر بيع محفوظ؛ يمكنك استرجاع إيصال العملية نفسها.'}</p>
        {recoveryStatus !== 'CANCELLED_UNCOMMITTED' &&
        <button type="button" disabled={isSubmitting} className="mt-2 min-h-11 rounded-lg bg-nw-warn-bg p-2"
          onClick={() => void executeSale('RECOVER_EXISTING')}>استرجاع محاولة البيع</button>}
        {recoveryBlocked && <button type="button" disabled={isSubmitting || !supabase}
          className="m-2 min-h-11 rounded-lg border border-nw-warn p-2" onClick={async () => {
            if (!supabase) return; setIsSubmitting(true);
            try {setAbsenceState(await inspectOrCancelPosV2Attempt(supabase,currentUser.id));}
            catch {setToast(operatorErrorMessage('inspect'), 'error');}
            finally {setIsSubmitting(false);}
          }}>التحقق من حالة المحاولة</button>}
        {absenceState === 'EXISTS' && <p>العملية مسجلة. استرجاع المحاولة هو الطريق الوحيد.</p>}
        {recoveryBlocked && (absenceState === 'ABSENT' || absenceState === 'CANCELLED_UNCOMMITTED') && <div>
          <p>الخادم لا يجد بيعاً مسجلاً لهذه المحاولة. سيعيد التحقق عند الإلغاء.</p>
          <label className="flex items-center gap-2 p-2"><input type="checkbox" checked={cancelConfirmed}
            disabled={isSubmitting} onChange={e => setCancelConfirmed(e.target.checked)}/>
            أؤكد إلغاء هذه المحاولة غير المسجلة وبدء بيع جديد</label>
          <button type="button" disabled={!cancelConfirmed || isSubmitting || !supabase}
            className="min-h-11 rounded-lg bg-nw-warn-bg text-nw-warn p-2 disabled:opacity-50" onClick={async () => {
              if (!supabase || !cancelConfirmed) return; setIsSubmitting(true);
              try {
                const outcome = await inspectOrCancelPosV2Attempt(supabase,currentUser.id,true);
                if (outcome === 'EXISTS') {setAbsenceState(outcome); return;}
                if (outcome !== 'CANCELLED_UNCOMMITTED') throw new Error('تعذر إثبات الإلغاء؛ السجل محفوظ.');
                refreshRecovery(); setToast('ألغيت المحاولة غير المسجلة؛ يمكنك بدء بيع جديد.', 'success');
              } catch {setToast(operatorErrorMessage('cancel'), 'error');}
              finally {setIsSubmitting(false);}
            }}>إلغاء المحاولة غير المسجلة</button>
        </div>}
      </div>}

        <div className="grid min-w-0 items-start gap-5 lg:grid-cols-[minmax(0,1fr)_380px]">
          <section className="min-w-0 space-y-4" aria-label="منتجات نقطة البيع">
            <div className="flex min-w-0 items-center gap-2">
              <SearchField emphasis ref={searchInputRef} label="البحث في منتجات نقطة البيع"
                placeholder="ابحث باسم المنتج أو الباركود أو رمز الصنف..." value={searchQuery}
                onKeyDown={event=>{
                  if(event.key!=='Enter'||event.nativeEvent.isComposing)return;
                  event.preventDefault();
                  const lookup=resolvePosProductCode(filteredProducts,searchQuery);
                  if(lookup.status==='found'){addToCart(lookup.product,'legacy_single_sku_parcel','search');setSearchQuery('');}
                  else setToast('انتظر ظهور الصنف المطابق للباركود أو رمز الصنف، أو اختره من البطاقات.','info');
                }}
                onChange={(e) => setSearchQuery(e.target.value)} className="min-w-0 flex-1" />
              <UiButton aria-label="مسح بالباركود (الكاميرا)" onClick={() => setIsBarcodeScannerOpen(true)} className="shrink-0 px-3">
                <Camera className="h-5 w-5" /><span className="hidden sm:inline">مسح الباركود</span>
              </UiButton>
            </div>
            <FilterChips touchSize label="أقسام المنتجات" value={selectedCategory} onChange={value => setSelectedCategory(value)}
              options={[{value: 'all',label: 'جميع الأقسام'},...categories.map(category=>({value:category.id,label:category.nameAr}))]} />
            <div className="flex flex-wrap items-center gap-2 text-sm">
              <label htmlFor="pos-warehouse">مستودع البيع</label>
              <WarehouseChoice options={branchWarehouses} value={warehouseId}>
              <select id="pos-warehouse" value={warehouseId} disabled={cartItems.length > 0 || isSubmitting || recoveryBlocked}
                onChange={e => setSelectedWarehouseId(e.target.value)} className="min-h-11 max-w-full rounded-xl border border-nw-border bg-nw-surface px-3 text-nw-text">
                <option value="">اختر المستودع</option>
                {branchWarehouses.map(w => <option key={w.id} value={w.id}>{w.name}</option>)}
              </select>
              </WarehouseChoice>
            </div>
            <div data-testid="pos-product-list" className="grid min-w-0 gap-3 lg:grid-cols-[repeat(auto-fill,minmax(240px,1fr))]">
              {productsError&&<Card role="alert" className="col-span-full text-nw-bad">{productsError}</Card>}
              {isProductsLoading&&filteredProducts.length===0&&!productsError&&<Card role="status" className="col-span-full text-nw-muted"><Loader2 className="h-5 w-5 animate-spin"/>جارٍ تحميل المنتجات…</Card>}
              {!isProductsLoading&&filteredProducts.length===0&&!productsError&&<Card className="col-span-full text-nw-muted">لا توجد منتجات مطابقة.</Card>}
              {filteredProducts.map(prod=>{
                const own=cartItems.filter(item=>item.productId===prod.id);
                return <PosProductCard key={prod.id} product={prod} stock={posWarehouseAvailable(prod,warehouseId)}
                  parcelQuantity={own.find(i=>i.v2Line.commercial_line_kind==='legacy_single_sku_parcel')?.quantity??0}
                  unitQuantity={own.find(i=>i.v2Line.commercial_line_kind==='base_unit')?.quantity??0}
                  disabled={isSubmitting||recoveryBlocked||!warehouseId} onAdd={mode=>addToCart(prod,mode)}
                  onReduce={mode=>{const item=own.find(i=>i.v2Line.commercial_line_kind===mode);if(item)updateQuantity(item.id,-1);}}/>;
              })}
            </div>
            {parcelOptions.length>0&&<section aria-label="الطرود المشكّلة المتاحة" className="mt-3 grid min-w-0 gap-3 lg:grid-cols-[repeat(auto-fill,minmax(240px,1fr))]">
              {parcelOptions.filter(option=>!searchQuery.trim()||option.nameAr.includes(searchQuery.trim())).map(option=><article key={option.parcelConfigurationId} className="space-y-2 rounded-2xl border border-nw-border bg-nw-surface p-3">
                <h3 className="font-bold">{option.nameAr}</h3>
                <UiButton disabled={isSubmitting||recoveryBlocked||!warehouseId} onClick={()=>{setEditingParcelId(null);setParcelOption(option);}} aria-label={'تركيب طرد: '+option.nameAr} className="w-full justify-start">+ طرد مشكّل <MoneyText amount={option.parcelPriceInMinorUnits/1000}/></UiButton>
                <p className="text-xs text-nw-muted">في السلة: <bdi dir="ltr">{cartItems.filter(i=>i.v2Line.commercial_line_kind==='configurable_parcel'&&i.v2Line.family_product_id===option.familyProductId).reduce((sum,i)=>sum+i.quantity,0)}</bdi> طرد مشكّل</p>
              </article>)}
            </section>}
          </section>
          <ResponsiveCartPanel open={isCartOpen} onClose={() => setIsCartOpen(false)} busy={isSubmitting}
            title={'سلة المبيعات الحالية (' + cartItems.length + ')'}
            action={cartItems.length > 0 && <UiButton variant="danger" disabled={isSubmitting || recoveryBlocked} onClick={() => setCartItems([])} className="px-2 text-xs"><Trash2 className="h-4 w-4" />إفراغ السلة</UiButton>}
            footer={<>{cartTotals}{paymentControl}{completeSaleButton}</>}>
            {cartMethodConflict&&<p role="alert" className="rounded-lg bg-nw-bad-bg p-3 text-sm text-nw-bad">{cartMethodConflict}</p>}
                      {/* Customer Picker */}
          <div className="space-y-2 rounded-2xl border border-nw-border bg-nw-bg/35 p-3">
            <div className="flex items-center justify-between gap-2">
              <span className="font-bold text-nw-text">العميل المستلم</span>
              <button
                type="button"
                onClick={() => setIsAddCustomerOpen(true)}
                className="min-h-11 flex items-center gap-1.5 rounded-xl border border-nw-ok/30 bg-nw-ok-bg/10 px-2.5 py-1.5 text-[10px] font-extrabold text-nw-ok transition hover:bg-nw-ok-bg/20"
              >
                <UserPlus className="h-3.5 w-3.5" />
                زبون جديد سريع
              </button>
            </div>
            <div className="relative">
              <Search className="pointer-events-none absolute right-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-nw-muted" />
              <input
                type="search"
                value={customerSearch}
                onChange={(event) => setCustomerSearch(event.target.value)}
                placeholder="ابحث بالاسم أو الهاتف أو معرف العميل"
                aria-label="البحث عن عميل للبيع"
                className="w-full rounded-xl border border-nw-border bg-nw-surface-2 min-h-11 py-2 pl-3 pr-9 text-xs text-nw-text placeholder:text-nw-muted focus:border-nw-ok focus:outline-none"
              />
            </div>
            <select aria-label="اختيار العميل"
              value={selectedCustomerId}
              onChange={(e) => setSelectedCustomerId(e.target.value)}
              className="w-full rounded-xl border border-nw-border bg-nw-surface-2 px-3 min-h-11 py-2 text-sm text-nw-text focus:border-nw-ok focus:outline-none"
            >
              <option value="">زبون نقدي - مباشر</option>
              {posCustomers.map((customer) => (
                <option key={customer.id} value={customer.id}>
                  {customer.name}
                  {customer.phone ? ` — ${customer.phone}` : ''}
                </option>
              ))}
            </select>
            {selectedPosCustomer && <div data-testid="pos-customer-debt" className={
              selectedPosCustomer.currentBalance !== undefined && selectedPosCustomer.creditLimit !== undefined
                && selectedPosCustomer.currentBalance > selectedPosCustomer.creditLimit
                ? 'flex flex-wrap items-center gap-2 text-xs text-nw-warn' : 'flex flex-wrap items-center gap-2 text-xs text-nw-muted'}>
              <span>{selectedPosCustomer.name}</span>
              {selectedPosCustomer.currentBalance !== undefined && Number.isFinite(selectedPosCustomer.currentBalance)
                ? <span>عليه <MoneyText amount={selectedPosCustomer.currentBalance} /></span> : <span>الدين غير متاح</span>}
              {selectedPosCustomer.creditLimit !== undefined && Number.isFinite(selectedPosCustomer.creditLimit) && <>
                <span>حد الدين <MoneyText amount={selectedPosCustomer.creditLimit} /></span>
                {selectedPosCustomer.currentBalance !== undefined && selectedPosCustomer.currentBalance > selectedPosCustomer.creditLimit && <span>تجاوز الحد</span>}
              </>}
            </div>}
            {selectedPosCustomer&&canReceiveCheque&&<UiButton disabled={isSubmitting||recoveryBlocked} onClick={()=>setIsChequeOpen(true)}>استلام شيك من العميل</UiButton>}
            <div className="flex items-center justify-between gap-2 text-[9px] text-nw-muted">
              <span>
                {isPosCustomersLoading
                  ? 'جاري البحث...'
                  : `${posCustomerTotal} عميل مطابق`}
              </span>
              {posCustomersHaveMore && (
                <button
                  type="button"
                  onClick={loadMorePosCustomers}
                  disabled={isPosCustomersLoading}
                  className="min-h-11 rounded-lg border border-nw-border bg-nw-surface-2 px-2 py-1 font-bold text-nw-text disabled:opacity-60"
                >
                  تحميل المزيد
                </button>
              )}
            </div>
            {paymentMethod === 'debt' && !selectedCustomerId ? (
              <p className="flex items-start gap-1.5 text-[10px] leading-5 text-nw-warn">
                <CircleAlert className="mt-0.5 h-3.5 w-3.5 shrink-0" />
                اختر عميلاً مسجلاً؛ لا يمكن حفظ دين على زبون نقدي مباشر.
              </p>
            ) : selectedPosCustomer ? (
              <p className="text-[10px] leading-5 text-nw-ok">
                ستُحفظ الفاتورة في سجل {selectedPosCustomer.name} وحسابه.
              </p>
            ) : (
              <p className="text-[10px] leading-5 text-nw-muted">
                للبيع النقدي العابر اترك الخيار على «زبون نقدي - مباشر».
              </p>
            )}
          </div>


                    {cartItems.length === 0 ? (
          <div className="py-6 text-center text-nw-muted text-xs">
            اختر + طرد أو + باكيت من بطاقة الصنف أعلاه لإضافته إلى الفاتورة
          </div>
        ) : (
          <div className="space-y-3">
            {cartItems.map((item) => (
              <div key={item.id} data-pos-cart-line className="flex flex-wrap items-center justify-between gap-2 border-b border-nw-border py-3 text-sm">
                <div className="min-w-0 w-full">
                  <div className="flex flex-wrap items-center gap-1"><h5 className="font-bold text-nw-text break-words">{item.productName}</h5><span data-pos-cart-line-kind className="text-xs font-bold">· {item.quantity} {item.v2Line.commercial_line_kind==='base_unit'?'باكيت':item.v2Line.commercial_line_kind==='legacy_single_sku_parcel'?'طرد':'طرد مشكّل'}</span></div>
                  <StatusBadge tone={item.v2Line.commercial_line_kind === 'configurable_parcel' ? 'warn' : 'info'}>{item.v2Line.commercial_line_kind === 'base_unit' ? 'باكيت' : item.v2Line.commercial_line_kind === 'legacy_single_sku_parcel' ? 'طرد' : 'طرد مشكّل'}</StatusBadge><span className="nw-num text-xs text-nw-muted">
                    {item.unitPrice.toFixed(3)} {CURRENCY} / {item.v2Line.commercial_line_kind==='base_unit'?'باكيت':item.v2Line.commercial_line_kind==='legacy_single_sku_parcel'?'طرد':'طرد مشكّل'}
                  </span>
                </div>

                <div className="flex flex-wrap items-center gap-2">
                  {item.v2Line.commercial_line_kind === 'configurable_parcel' && <button type="button"
                    disabled={isSubmitting || recoveryBlocked} className="min-h-11 rounded-lg bg-nw-info-bg text-nw-info p-2"
                    onClick={() => {
                      const line = item.v2Line;
                      if (line.commercial_line_kind !== 'configurable_parcel') return;
                      const option = parcelOptions.find(o => o.parcelConfigurationId === line.parcel_configuration_id
                        && o.configurationRevision === line.configuration_revision);
                      if (!option) {setToast('تغير إعداد الطرد؛ احذف هذا الطرد وأعد تركيبه.', 'error'); return;}
                      setEditingParcelId(item.id); setParcelOption(option);
                    }}>تعديل الطرد</button>}
                  <div className="flex items-center gap-1.5 bg-nw-surface px-2 py-1 rounded-lg border border-nw-border">
                    <button disabled={isSubmitting || recoveryBlocked} aria-label={`تقليل ${item.productName}`} onClick={() => updateQuantity(item.id, -1)} className="flex h-11 w-11 items-center justify-center text-nw-text">
                      <Minus className="w-3 h-3" />
                    </button>
                    <span data-pos-quantity={item.id} className="nw-num font-bold text-nw-text px-1">{item.quantity}</span>
                    <button disabled={isSubmitting || recoveryBlocked || item.v2Line.commercial_line_kind === 'configurable_parcel'} aria-label={`زيادة ${item.productName}`} onClick={() => updateQuantity(item.id, 1)} className="min-h-11 text-nw-muted hover:text-nw-text">
                      <Plus className="w-3 h-3" />
                    </button>
                  </div>
                  <span className="nw-num whitespace-nowrap font-bold text-nw-text text-left">
                    {item.totalPrice.toFixed(3)} {CURRENCY}
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}


          {paymentMethod==='debt'&&cartItems.length>0&&<fieldset disabled={isSubmitting||recoveryBlocked} className="min-w-0 space-y-3 rounded-xl border border-nw-border bg-nw-surface-2 p-3">
            <legend className="px-1 font-bold">دفعة جزئية والباقي على الحساب</legend>
            <label className="block space-y-2 text-sm" htmlFor="pos-initial-paid"><span className="block">المدفوع الآن</span>
              <input id="pos-initial-paid" type="text" inputMode="decimal" enterKeyHint="done" maxLength={18} value={initialPaidText}
                onChange={event=>setInitialPaidText(event.target.value)} placeholder="0.000" dir="ltr" aria-invalid={Boolean(initialPaidIssue)} aria-describedby="pos-initial-paid-help"
                className="block min-h-11 w-full rounded-xl border border-nw-border bg-nw-surface px-3 py-2 text-base text-nw-text"/>
            </label>
            <SegmentedControl touchSize label="طريقة المدفوع الآن" value={initialPaidMethod} options={[{value:'cash' as const,label:'كاش'},{value:'cliq' as const,label:'CliQ'}]} onChange={setInitialPaidMethod}/>
            {initialPaidMethod==='cliq'&&<label className="block space-y-2 text-sm" htmlFor="pos-initial-reference"><span className="block">مرجع CliQ (اختياري)</span>
              <input id="pos-initial-reference" value={initialPaidReference} maxLength={200} enterKeyHint="done" onChange={event=>setInitialPaidReference(event.target.value)}
                className="block min-h-11 w-full rounded-xl border border-nw-border bg-nw-surface px-3 py-2 text-base text-nw-text"/>
            </label>}
            <p id="pos-initial-paid-help" className={initialPaidIssue?'text-sm text-nw-bad':'text-sm text-nw-muted'} role={initialPaidIssue?'alert':undefined}>
              {initialPaidIssue??<>الباقي على الحساب: <MoneyText amount={initialDue??totalAmount} currency/>. صفر يعني ديناً كاملاً؛ دفع الصافي كله يعني دفعاً كاملاً.</>}
            </p>
          </fieldset>}

                      {/* Received Cash Input */}
          {paymentMethod === 'cash' && cartItems.length > 0 && (
            <div className="flex items-center justify-between bg-nw-surface-2/80 p-2.5 rounded-xl border border-nw-border">
              <div>
                <span className="text-[11px] text-nw-text font-bold block">المبلغ المستلم:</span>
                <span className="text-[10px] text-nw-ok">الباقي: {changeDue.toFixed(3)} {CURRENCY}</span>
              </div>
              <input inputMode="decimal" enterKeyHint="done" aria-label="المبلغ المستلم"
                type="number"
                value={cashReceived || ''}
                onChange={(e) => setCashReceived(parseFloat(e.target.value) || 0)}
                placeholder={totalAmount.toFixed(3)}
                className="min-h-11 w-28 bg-nw-surface border border-nw-border rounded-lg px-2 py-1 text-left font-bold text-nw-text text-xs focus:outline-none focus:border-nw-ok"
              />
            </div>
          )}


          </ResponsiveCartPanel>
        </div>
      </div>
      <StickyActionBar tone="hero" hidden={isCartOpen} data-testid="pos-sticky-checkout">
        <div className="flex min-w-0 items-center justify-between gap-2">
          <strong className="text-xl"><MoneyText amount={totalAmount} currency /></strong>
          <UiButton aria-label="مراجعة السلة والعميل" onClick={() => setIsCartOpen(true)} className="px-2 text-xs"><ShoppingBag className="h-4 w-4" />{formatItemCount(cartItems.length)} · السلة</UiButton>
        </div>
        <div className="grid grid-cols-1 items-center gap-2">{paymentControl}{completeSaleButton}</div>
      </StickyActionBar>
      {showReceiptModal&&lastInvoice&&<SaleReceiptDialog completed receipt={invoiceReceipt(lastInvoice,receiptBranch)}
        onClose={()=>setShowReceiptModal(false)} onShare={()=>void handleShareReceipt()} onCopy={()=>void handleCopyReceiptLink()}/>}

      {parcelOption && <PosParcelBuilder option={parcelOption}
        initialComponents={(() => {const line = cartItems.find(i => i.id === editingParcelId)?.v2Line;
          return line?.commercial_line_kind === 'configurable_parcel' ? line.parcel_instances[0].components : undefined;})()}
        onClose={() => {setParcelOption(null); setEditingParcelId(null);}} onAdd={addParcel}/>}
      {/* Live Barcode Camera Scanner Modal */}
      {isBarcodeScannerOpen && (
        <Suspense
          fallback={
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-nw-bg/85 p-4" dir="rtl">
              <div className="flex items-center gap-2 rounded-2xl border border-nw-border bg-nw-surface px-4 py-3 text-xs font-bold text-nw-text shadow-2xl">
                <Loader2 className="h-4 w-4 animate-spin text-nw-ok" />
                <span>جاري فتح قارئ الباركود...</span>
              </div>
            </div>
          }
        >
          <BarcodeScannerModal
            isOpen={isBarcodeScannerOpen}
            onClose={() => setIsBarcodeScannerOpen(false)}
            resolveProductCode={resolveScannedProductCode}
            onProductScanned={(scannedProduct) => addToCart(scannedProduct,'legacy_single_sku_parcel','barcode')}
            setToast={setToast}
          />
        </Suspense>
      )}

      <Modal isOpen={isChequeOpen} onClose={()=>setIsChequeOpen(false)} title="استلام شيك عميل" confirmUnsavedClose>
        {isChequeOpen&&selectedPosCustomer&&<ChequeRegistrationForm direction="incoming" partyId={selectedPosCustomer.id}
          parties={[selectedPosCustomer]} branchId={activeBranch?.id??null} onClose={()=>setIsChequeOpen(false)}
          onSaved={result=>{const balance=result.customerBalanceInMinorUnits;if(balance!==null)setPosCustomers(rows=>rows.map(c=>c.id===result.cheque.customerId
            ?{...c,currentBalance:balance/1000}:c));setIsChequeOpen(false);setToast('تم استلام الشيك دون حركة على الدرج.','success');}} />}
      </Modal>
      <Modal
        isOpen={isAddCustomerOpen}
        onClose={() => setIsAddCustomerOpen(false)}
        title="زبون جديد سريع"
        subtitle="سيُحفظ في العملاء ويُختار لهذه الفاتورة مباشرة"
      >
        <AddCustomerModalContent
          quick
          onClose={() => setIsAddCustomerOpen(false)}
          onCreated={handleCustomerCreated}
        />
      </Modal>
    </div>
  );
};

src/features/products/ProductDetailModal.beforeText:
import {Card,FormFields,UiButton,formatJod} from '../../components/ui';
import React, { useCallback, useState } from 'react';
import {
  AlertTriangle,
  ArrowDown,
  ArrowUp,
  Boxes,
  Camera,
  Edit3,
  Eye,
  EyeOff,
  Image,
  Layers3,
  Palette,
  Plus,
  ReceiptText,
  Tag,
  Upload,
  X,
} from 'lucide-react';
import { BarcodeCameraCaptureModal } from '../barcode/BarcodeCameraCaptureModal';
import type { StartBarcodeCamera } from '../barcode/barcodeCamera';
import { CURRENCY } from '../../constants';
import {
  removeUploadedProductImage,
  uploadProductImageToSupabase,
} from '../../services/supabase/product-images.service';
import {
  createProductFlavorInSupabase,
  reorderProductFlavorsInSupabase,
  updateProductFlavorInSupabase,
} from '../../services/supabase/products.service';
import { useAppStore } from '../../stores/useAppStore';
import { useAuthStore } from '../../stores/useAuthStore';
import {canUseSupplierReplacement} from '../../utils/supplierReplacement';
import { ProductCostCorrectionPanel } from './ProductCostCorrectionPanel';
import type { ProductEditComparisonRow, ProductEditSnapshot } from '../../utils/productEditConflict';
import { ProductEditConflictPanel } from './ProductEditConflictPanel';
import { Product } from '../../types';
import {
  formatProductInventory,
  formatWholesaleInventory,
  summarizeFlavorFamilyInventory,
} from '../../utils/inventoryFormatter';
import { validateProductImage } from '../../utils/productImage';
import { calculateProductProfit } from '../../utils/productCalculations';
import { validateProductBarcode } from '../../utils/productIdentifiers';

interface ProductDetailModalProps {
  product: Product;
  onClose: () => void;
  startBarcodeScanner?: StartBarcodeCamera;
}

export const ProductDetailModal: React.FC<ProductDetailModalProps> = ({
  product,
  onClose,
  startBarcodeScanner,
}) => {
  const {
    categories,
    products,
    hideProduct,
    openModal,
    refreshProductsFromSupabase,
    setToast,
  } = useAppStore();
  const { roleName,roles } = useAuthStore();
  const [showCostCorrection, setShowCostCorrection] = useState(false);
  const [imageFailed, setImageFailed] = useState(false);
  const [showVisibilityConfirm, setShowVisibilityConfirm] = useState(false);
  const [isUpdatingVisibility, setIsUpdatingVisibility] = useState(false);
  const [showFlavorForm, setShowFlavorForm] = useState(false);
  const [flavorName, setFlavorName] = useState('');
  const [flavorBarcode, setFlavorBarcode] = useState('');
  const [flavorImage, setFlavorImage] = useState<File | null>(null);
  const [flavorImagePreview, setFlavorImagePreview] = useState('');
  const [isSavingFlavor, setIsSavingFlavor] = useState(false);
  const [editingFlavorId, setEditingFlavorId] = useState<string | null>(null);
  const [editFlavorName, setEditFlavorName] = useState('');
  const [editFlavorBarcode, setEditFlavorBarcode] = useState('');
  const [editFlavorActive, setEditFlavorActive] = useState(true);
  const [editFlavorImage, setEditFlavorImage] = useState<File | null>(null);
  const [editFlavorImagePreview, setEditFlavorImagePreview] = useState('');
  // Version and values the flavor edit started from (migration 170).
  const [flavorOpened, setFlavorOpened] = useState<{
    version: string;
    name: string;
    barcode: string;
    active: boolean;
  } | null>(null);
  const [flavorConflict, setFlavorConflict] = useState<ProductEditSnapshot | null>(null);
  const [isUpdatingFlavor, setIsUpdatingFlavor] = useState(false);
  const [isReorderingFlavors, setIsReorderingFlavors] = useState(false);
  const [barcodeCameraTarget, setBarcodeCameraTarget] = useState<
    'new' | 'edit' | null
  >(null);

  const flavors = products
    .filter((item) => item.flavorMasterProductId === product.id)
    .sort(
      (first, second) =>
        (first.flavorSortOrder || 0) - (second.flavorSortOrder || 0) ||
        (first.flavorNameAr || '').localeCompare(second.flavorNameAr || '', 'ar')
    );
  const isFlavorFamily = product.isFlavorMaster || flavors.length > 0;
  const familyInventorySummary = summarizeFlavorFamilyInventory(flavors);
  const familyInventoryProduct: Product = isFlavorFamily
    ? {
        ...product,
        onHandQuantity: familyInventorySummary.onHandQuantity,
        reservedQuantity: familyInventorySummary.reservedQuantity,
        availableQuantity: familyInventorySummary.availableQuantity,
      }
    : product;

  const category = categories.find(
    (item) => item.id === product.categoryId
  );
  const unitsPerSalePackage = product.unitsPerSalePackage || 1;
  const salePackagePrice = product.salePackagePrice || 0;
  const salePackageCost =
    product.costPrice * unitsPerSalePackage;
  const needsSalePackageSetup =
    !product.saleUnitId ||
    !product.salePackage ||
    salePackagePrice <= 0;
  const salePackageProfit = calculateProductProfit(
    salePackagePrice,
    salePackageCost
  );
  const inventoryOnHand = formatProductInventory(familyInventoryProduct, false);
  const inventoryAvailable = formatProductInventory(familyInventoryProduct, true);
  const familyReserved = formatWholesaleInventory(
    familyInventorySummary.reservedQuantity,
    familyInventorySummary.unitsPerPackage,
    familyInventorySummary.purchasePackage,
    familyInventorySummary.unit
  );
  const isOutOfStock = familyInventoryProduct.availableQuantity === 0;
  const isLowStock =
    familyInventoryProduct.availableQuantity > 0 &&
    familyInventoryProduct.availableQuantity <= product.reorderLevel;
  const reorderSalePackages = Math.ceil(
    Math.max(0, product.reorderLevel || 0) / unitsPerSalePackage
  );
  const maxStockSalePackages =
    product.maxStockLevel === undefined
      ? undefined
      : Math.ceil(
          Math.max(0, product.maxStockLevel) / unitsPerSalePackage
        );

  const resetFlavorForm = () => {
    if (flavorImagePreview) URL.revokeObjectURL(flavorImagePreview);
    setFlavorName('');
    setFlavorBarcode('');
    setFlavorImage(null);
    setFlavorImagePreview('');
    setShowFlavorForm(false);
    setBarcodeCameraTarget(null);
  };

  const selectFlavorImage = (file?: File) => {
    if (!file) return;
    const validationError = validateProductImage(file);
    if (validationError) {
      setToast(validationError, 'error');
      return;
    }
    if (flavorImagePreview) URL.revokeObjectURL(flavorImagePreview);
    setFlavorImage(file);
    setFlavorImagePreview(URL.createObjectURL(file));
  };

  const saveFlavor = async () => {
    if (!flavorName.trim()) {
      setToast('اكتب اسم النكهة.', 'error');
      return;
    }

    const barcodeValidation = validateProductBarcode(products, {
      barcode: flavorBarcode,
    });
    if (barcodeValidation.valid === false) {
      setToast(barcodeValidation.message, 'error');
      return;
    }

    setIsSavingFlavor(true);
    let uploadedStoragePath = '';
    try {
      let imageUrl = '';
      if (flavorImage) {
        const upload = await uploadProductImageToSupabase(flavorImage);
        if (!upload.success || !upload.publicUrl) {
          throw new Error(upload.error || 'تعذر رفع صورة النكهة.');
        }
        imageUrl = upload.publicUrl;
        uploadedStoragePath = upload.storagePath || '';
      }

      const result = await createProductFlavorInSupabase({
        masterProductId: product.id,
        flavorNameAr: flavorName,
        warehouseId: product.warehouseId,
        imageUrl,
        barcode: flavorBarcode,
      });

      if (!result.success) {
        if (uploadedStoragePath) {
          await removeUploadedProductImage(uploadedStoragePath);
        }
        setToast(result.error || 'تعذر إضافة النكهة.', 'error');
        return;
      }

      await refreshProductsFromSupabase();
      setToast(result.message || 'تمت إضافة النكهة بنجاح.', 'success');
      resetFlavorForm();
    } catch (error) {
      if (uploadedStoragePath) {
        await removeUploadedProductImage(uploadedStoragePath).catch(() => undefined);
      }
      setToast(
        error instanceof Error ? error.message : 'تعذر إضافة النكهة.',
        'error'
      );
    } finally {
      setIsSavingFlavor(false);
    }
  };

  const cancelFlavorEdit = () => {
    if (editFlavorImagePreview) {
      URL.revokeObjectURL(editFlavorImagePreview);
    }
    setEditingFlavorId(null);
    setEditFlavorName('');
    setEditFlavorBarcode('');
    setEditFlavorActive(true);
    setEditFlavorImage(null);
    setEditFlavorImagePreview('');
    setFlavorOpened(null);
    setFlavorConflict(null);
    setBarcodeCameraTarget((target) => (target === 'edit' ? null : target));
  };

  const startFlavorEdit = (flavor: Product) => {
    cancelFlavorEdit();
    setEditingFlavorId(flavor.id);
    setEditFlavorName(flavor.flavorNameAr || '');
    setEditFlavorBarcode(flavor.barcode || '');
    setEditFlavorActive(flavor.status !== 'hidden');
    setFlavorOpened({
      version: flavor.updatedAt,
      name: flavor.flavorNameAr || '',
      barcode: flavor.barcode || '',
      active: flavor.status !== 'hidden',
    });
  };

  const flavorConflictRows = (): ProductEditComparisonRow[] => {
    if (!flavorConflict || !flavorOpened) return [];
    const rows: ProductEditComparisonRow[] = [
      { field: 'nameAr', label: 'اسم النكهة', mine: editFlavorName.trim(), current: flavorConflict.flavorNameAr,
        changedByMe: editFlavorName.trim() !== flavorOpened.name, changedByOther: flavorConflict.flavorNameAr !== flavorOpened.name },
      { field: 'barcode', label: 'الباركود', mine: editFlavorBarcode.trim(), current: flavorConflict.barcode,
        changedByMe: editFlavorBarcode.trim() !== flavorOpened.barcode, changedByOther: flavorConflict.barcode !== flavorOpened.barcode },
    ];
    return rows.filter((row) => row.changedByMe || row.changedByOther);
  };

  const reapplyFlavorEdits = () => {
    if (!flavorConflict || !flavorOpened) return;
    // My changed fields over the current values; untouched fields take the current value.
    if (editFlavorName.trim() === flavorOpened.name) setEditFlavorName(flavorConflict.flavorNameAr);
    if (editFlavorBarcode.trim() === flavorOpened.barcode) setEditFlavorBarcode(flavorConflict.barcode);
    if (editFlavorActive === flavorOpened.active) setEditFlavorActive(flavorConflict.isActive);
    setFlavorOpened({
      version: flavorConflict.updatedAt,
      name: flavorConflict.flavorNameAr,
      barcode: flavorConflict.barcode,
      active: flavorConflict.isActive,
    });
    setFlavorConflict(null);
    setToast('طُبّقت تعديلاتك فوق القيم الحالية. راجعها ثم احفظ.', 'success');
  };

  const selectEditFlavorImage = (file?: File) => {
    if (!file) return;
    const validationError = validateProductImage(file);
    if (validationError) {
      setToast(validationError, 'error');
      return;
    }
    if (editFlavorImagePreview) {
      URL.revokeObjectURL(editFlavorImagePreview);
    }
    setEditFlavorImage(file);
    setEditFlavorImagePreview(URL.createObjectURL(file));
  };

  const saveFlavorChanges = async (flavor: Product) => {
    if (!editFlavorName.trim()) {
      setToast('اكتب اسم النكهة.', 'error');
      return;
    }

    const barcodeValidation = validateProductBarcode(products, {
      barcode: editFlavorBarcode,
      currentProductId: flavor.id,
    });
    if (barcodeValidation.valid === false) {
      setToast(barcodeValidation.message, 'error');
      return;
    }

    setIsUpdatingFlavor(true);
    let uploadedStoragePath = '';
    let flavorWasPersisted = false;
    try {
      let imageUrl = flavor.imageUrl || '';
      if (editFlavorImage) {
        const upload = await uploadProductImageToSupabase(editFlavorImage);
        if (!upload.success || !upload.publicUrl) {
          throw new Error(upload.error || 'تعذر رفع صورة النكهة.');
        }
        imageUrl = upload.publicUrl;
        uploadedStoragePath = upload.storagePath || '';
      }

      const result = await updateProductFlavorInSupabase({
        flavorProductId: flavor.id,
        flavorNameAr: editFlavorName,
        barcode: editFlavorBarcode,
        imageUrl,
        isActive: editFlavorActive,
        expectedUpdatedAt: flavorOpened?.version || flavor.updatedAt,
      });

      if (!result.success) {
        if (uploadedStoragePath) {
          await removeUploadedProductImage(uploadedStoragePath);
        }
        if (result.errorDetails?.code === 'PRODUCT_EDIT_CONFLICT' && result.conflict) {
          setFlavorConflict(result.conflict);
          setToast(result.error || 'عدّل مستخدم آخر هذا المنتج قبل قليل.', 'error');
          return;
        }
        setToast(result.error || 'تعذر تحديث النكهة.', 'error');
        return;
      }

      flavorWasPersisted = true;
      await refreshProductsFromSupabase();
      setToast(result.message || 'تم تحديث النكهة.', 'success');
      cancelFlavorEdit();
    } catch (error) {
      if (!flavorWasPersisted && uploadedStoragePath) {
        await removeUploadedProductImage(uploadedStoragePath).catch(
          () => undefined
        );
      }
      setToast(
        error instanceof Error ? error.message : 'تعذر تحديث النكهة.',
        'error'
      );
    } finally {
      setIsUpdatingFlavor(false);
    }
  };

  const moveFlavor = async (index: number, direction: -1 | 1) => {
    const targetIndex = index + direction;
    if (targetIndex < 0 || targetIndex >= flavors.length) return;

    const orderedIds = flavors.map((flavor) => flavor.id);
    [orderedIds[index], orderedIds[targetIndex]] = [
      orderedIds[targetIndex],
      orderedIds[index],
    ];

    setIsReorderingFlavors(true);
    const result = await reorderProductFlavorsInSupabase(
      product.id,
      orderedIds
    );
    setIsReorderingFlavors(false);

    if (!result.success) {
      setToast(result.error || 'تعذر ترتيب النكهات.', 'error');
      return;
    }
    await refreshProductsFromSupabase();
    setToast(result.message || 'تم ترتيب النكهات.', 'success');
  };

  const captureFlavorBarcode = useCallback(
    (value: string) => {
      const capturedBarcode = value.trim();
      const currentProductId =
        barcodeCameraTarget === 'edit' ? editingFlavorId || undefined : undefined;
      const validation = validateProductBarcode(products, {
        barcode: capturedBarcode,
        currentProductId,
      });

      if (barcodeCameraTarget === 'edit') {
        setEditFlavorBarcode(capturedBarcode);
      } else {
        setFlavorBarcode(capturedBarcode);
      }

      if (validation.valid === false) {
        setToast(validation.message, 'error');
        return;
      }
      setToast('تمت قراءة باركود النكهة وتعبئة الحقل.', 'success');
    },
    [barcodeCameraTarget, editingFlavorId, products, setToast]
  );

  const changeVisibility = async () => {
    setIsUpdatingVisibility(true);
    const result = await hideProduct(product.id);
    setIsUpdatingVisibility(false);
    if (result?.success) onClose();
  };

  return (
    <FormFields dir="rtl" className="nw-products-fields min-w-0 space-y-4 text-nw-text text-sm">
      <Card padded={false} className="overflow-hidden rounded-3xl border border-nw-border bg-nw-surface">
        <div className="relative flex h-40 items-center justify-center   ">
          {product.imageUrl && !imageFailed ? (
            <img
              src={product.imageUrl}
              alt={product.nameAr}
              onError={() => setImageFailed(true)}
              className="h-full w-full object-cover"
            />
          ) : (
            <Image className="h-11 w-11 text-nw-muted" />
          )}
          <span
            className={`absolute right-3 top-3 rounded-full border px-2.5 py-1 text-xs font-black ${
              product.status === 'hidden'
                ? 'border-nw-border bg-nw-surface-2 text-nw-muted'
                : isOutOfStock
                  ? 'border-nw-border bg-nw-bad-bg text-nw-bad'
                  : isLowStock
                    ? 'border-nw-border bg-nw-warn-bg text-nw-warn'
                    : 'border-nw-border bg-nw-ok-bg text-nw-ok'
            }`}
          >
            {product.status === 'hidden'
              ? 'مخفي'
              : isOutOfStock
                ? 'نافد'
                : isLowStock
                  ? 'مخزون منخفض'
                  : 'متوفر'}
          </span>
        </div>

        <div className="space-y-2.5 p-4">
          <div>
            <p className="mb-1 text-xs font-bold text-nw-info">
              {category?.nameAr || 'بدون قسم'}
            </p>
            <h3 className="text-base font-black text-nw-text">
              {product.nameAr}
            </h3>
            {product.description && (
              <p className="mt-1 text-xs leading-5 text-nw-muted">
                {product.description}
              </p>
            )}
          </div>
          <div className="flex flex-wrap gap-1.5 border-t border-nw-border pt-2.5 font-mono text-xs text-nw-text">
            <span className="rounded-lg bg-nw-surface-2 px-2 py-1">
              رمز الصنف: {product.sku}
            </span>
            {product.barcode && (
              <span className="rounded-lg bg-nw-surface-2 px-2 py-1">
                Barcode: {product.barcode}
              </span>
            )}
          </div>
        </div>
      </Card>

      {!product.flavorMasterProductId && (
        <Card padded={false} className="rounded-2xl border border-nw-border    p-3.5">
          <div className="flex items-start justify-between gap-3">
            <div className="flex min-w-0 items-start gap-2">
              <Palette className="mt-0.5 h-4 w-4 shrink-0 text-nw-info" />
              <div>
                <h4 className="font-black text-nw-text">النكهات</h4>
                <p className="mt-0.5 text-xs leading-4 text-nw-muted">
                  السعر والطرد من المنتج الأساسي، والمخزون مستقل لكل نكهة.
                </p>
              </div>
            </div>
            <UiButton variant="plain"
              type="button"
              onClick={() => setShowFlavorForm((value) => !value)}
              className="flex shrink-0 items-center gap-1 rounded-xl bg-nw-primary px-2.5 py-2 text-xs font-black text-nw-on-primary"
            >
              {showFlavorForm ? <X className="h-3.5 w-3.5" /> : <Plus className="h-3.5 w-3.5" />}
              {showFlavorForm ? 'إغلاق' : 'إضافة نكهة'}
            </UiButton>
          </div>

          {showFlavorForm && (
            <div className="mt-3 space-y-2 rounded-2xl border border-nw-border bg-nw-surface p-3">
              <label className="block">
                <span className="mb-1 block text-xs font-bold text-nw-muted">اسم النكهة *</span>
                <input
                  value={flavorName}
                  onChange={(event) => setFlavorName(event.target.value)}
                  placeholder="مثال: جبنة"
                  className="w-full rounded-xl border border-nw-border bg-nw-surface-2 px-3 py-2.5 text-sm font-bold text-nw-text outline-none focus:border-nw-border"
                />
              </label>
              <label className="block">
                <span className="mb-1 block text-xs font-bold text-nw-muted">الباركود (اختياري)</span>
                <span className="flex gap-1.5">
                  <input
                    value={flavorBarcode}
                    onChange={(event) => setFlavorBarcode(event.target.value)}
                    inputMode="text"
                    aria-label="باركود النكهة الجديدة"
                    placeholder="أدخله يدويًا أو امسحه بالكاميرا"
                    className="min-w-0 flex-1 rounded-xl border border-nw-border bg-nw-surface-2 px-3 py-2.5 text-sm font-bold text-nw-text outline-none focus:border-nw-border"
                  />
                  <UiButton variant="plain"
                    type="button"
                    onClick={() => setBarcodeCameraTarget('new')}
                    aria-label="مسح باركود النكهة الجديدة بالكاميرا"
                    title="مسح الباركود بالكاميرا"
                    className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-nw-border bg-nw-info-bg text-nw-info"
                  >
                    <Camera className="h-4 w-4" />
                  </UiButton>
                </span>
              </label>
              <div className="grid gap-2">
                <label className="flex cursor-pointer flex-col justify-end">
                  <span className="mb-1 block text-xs font-bold text-nw-muted">صورة النكهة (اختياري)</span>
                  <span className="flex h-11 items-center justify-center gap-1.5 rounded-xl border border-dashed border-nw-border bg-nw-surface-2 text-xs font-bold text-nw-text">
                    <Upload className="h-3.5 w-3.5" />
                    {flavorImage ? 'تغيير الصورة' : 'اختر صورة'}
                  </span>
                  <input
                    type="file"
                    accept="image/jpeg,image/png,image/webp"
                    className="hidden"
                    onChange={(event) => selectFlavorImage(event.target.files?.[0])}
                  />
                </label>
              </div>
              {flavorImagePreview && (
                <img src={flavorImagePreview} alt="معاينة النكهة" className="h-20 w-full rounded-xl bg-nw-surface-2 object-contain" />
              )}
              <p className="rounded-xl border border-nw-border bg-nw-ok-bg p-2 text-xs font-bold leading-4 text-nw-ok">
                تُنشأ النكهة برصيد صفر. استلم كميتها الفعلية لاحقًا من شاشة الاستلام.
              </p>
              {!isFlavorFamily && product.onHandQuantity > 0 && (
                <p className="rounded-xl border border-nw-border bg-nw-warn-bg p-2 text-xs font-bold leading-4 text-nw-warn">
                  رصيد المنتج الأساسي حاليًا ليس صفرًا. صفّر رصيده بالجرد أولًا، ثم وزّع الرصيد على النكهات حتى لا تختلط الكميات.
                </p>
              )}
              <UiButton variant="plain"
                type="button"
                onClick={() => void saveFlavor()}
                disabled={isSavingFlavor}
                className="w-full rounded-xl bg-nw-primary py-2.5 text-xs font-black text-nw-on-primary disabled:opacity-50"
              >
                {isSavingFlavor ? 'جاري الحفظ...' : 'حفظ تعريف النكهة'}
              </UiButton>
            </div>
          )}

          {flavors.length > 0 ? (
            <div className="mt-3 grid gap-2">
              {flavors.map((flavor, index) => {
                const flavorAvailable = formatProductInventory(flavor, true);
                const out = flavor.availableQuantity <= 0;
                const isHidden = flavor.status === 'hidden';
                const isEditingFlavor = editingFlavorId === flavor.id;
                return (
                  <div
                    key={flavor.id}
                    className={`rounded-2xl border bg-nw-surface-2 p-2.5 ${
                      isEditingFlavor
                        ? 'border-nw-border'
                        : 'border-nw-border'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      <div className="h-11 w-11 shrink-0 overflow-hidden rounded-xl bg-nw-surface">
                        {flavor.imageUrl ? (
                          <img src={flavor.imageUrl} alt={flavor.flavorNameAr} className="h-full w-full object-cover" />
                        ) : (
                          <Palette className="m-3 h-5 w-5 text-nw-muted" />
                        )}
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="flex flex-wrap items-center gap-1.5">
                          <strong className="truncate text-xs text-nw-text">{flavor.flavorNameAr}</strong>
                          <span className={`rounded-full px-2 py-0.5 text-xs font-black ${
                            isHidden
                              ? 'bg-nw-mute-bg text-nw-text'
                              : out
                                ? 'bg-nw-bad-bg text-nw-bad'
                                : 'bg-nw-ok-bg text-nw-ok'
                          }`}>
                            {isHidden ? 'متوقفة' : out ? 'نافدة' : 'متوفرة'}
                          </span>
                        </div>
                        <p className="mt-1 text-xs font-bold text-nw-muted">
                          المتاح: {flavorAvailable.cartonFormatted}
                          {flavor.barcode ? ` • ${flavor.barcode}` : ''}
                        </p>
                      </div>

                      <div className="flex shrink-0 items-center gap-1">
                        <div className="grid grid-cols-2 overflow-hidden rounded-lg border border-nw-border">
                          <UiButton variant="plain"
                            type="button"
                            aria-label="تحريك النكهة للأعلى"
                            disabled={index === 0 || isReorderingFlavors}
                            onClick={() => void moveFlavor(index, -1)}
                            className="p-1.5 text-nw-muted transition hover:text-nw-info disabled:opacity-25"
                          >
                            <ArrowUp className="h-3 w-3" />
                          </UiButton>
                          <UiButton variant="plain"
                            type="button"
                            aria-label="تحريك النكهة للأسفل"
                            disabled={
                              index === flavors.length - 1 ||
                              isReorderingFlavors
                            }
                            onClick={() => void moveFlavor(index, 1)}
                            className="border-r border-nw-border p-1.5 text-nw-muted transition hover:text-nw-info disabled:opacity-25"
                          >
                            <ArrowDown className="h-3 w-3" />
                          </UiButton>
                        </div>
                        <UiButton variant="plain"
                          type="button"
                          onClick={() =>
                            isEditingFlavor
                              ? cancelFlavorEdit()
                              : startFlavorEdit(flavor)
                          }
                          className="flex h-8 w-8 items-center justify-center rounded-lg border border-nw-border bg-nw-info-bg text-nw-info"
                          aria-label={isEditingFlavor ? 'إغلاق التعديل' : 'تعديل النكهة'}
                        >
                          {isEditingFlavor ? (
                            <X className="h-3.5 w-3.5" />
                          ) : (
                            <Edit3 className="h-3.5 w-3.5" />
                          )}
                        </UiButton>
                      </div>
                    </div>

                    {isEditingFlavor && (
                      <div className="mt-2.5 space-y-2 border-t border-nw-border pt-2.5">
                        <div className="grid grid-cols-2 gap-2">
                          <label>
                            <span className="mb-1 block text-xs font-bold text-nw-muted">
                              اسم النكهة *
                            </span>
                            <input
                              value={editFlavorName}
                              onChange={(event) =>
                                setEditFlavorName(event.target.value)
                              }
                              className="w-full rounded-xl border border-nw-border bg-nw-surface px-2.5 py-2 text-xs font-bold text-nw-text outline-none focus:border-nw-border"
                            />
                          </label>
                          <label>
                            <span className="mb-1 block text-xs font-bold text-nw-muted">
                              الباركود (اختياري)
                            </span>
                            <span className="flex gap-1">
                              <input
                                value={editFlavorBarcode}
                                onChange={(event) =>
                                  setEditFlavorBarcode(event.target.value)
                                }
                                inputMode="text"
                                aria-label={`باركود نكهة ${flavor.flavorNameAr || flavor.nameAr}`}
                                className="min-w-0 flex-1 rounded-xl border border-nw-border bg-nw-surface px-2.5 py-2 text-xs font-bold text-nw-text outline-none focus:border-nw-border"
                              />
                              <UiButton variant="plain"
                                type="button"
                                onClick={() => setBarcodeCameraTarget('edit')}
                                aria-label={`مسح باركود نكهة ${flavor.flavorNameAr || flavor.nameAr} بالكاميرا`}
                                title="مسح الباركود بالكاميرا"
                                className="flex h-8 w-8 shrink-0 items-center justify-center rounded-xl border border-nw-border bg-nw-info-bg text-nw-info"
                              >
                                <Camera className="h-3.5 w-3.5" />
                              </UiButton>
                            </span>
                          </label>
                        </div>

                        <div className="grid grid-cols-2 gap-2">
                          <label className="flex cursor-pointer items-center justify-center gap-1.5 rounded-xl border border-dashed border-nw-border bg-nw-surface px-2 py-2 text-xs font-bold text-nw-text">
                            <Upload className="h-3.5 w-3.5" />
                            {editFlavorImage ? 'تم اختيار صورة جديدة' : 'تغيير الصورة'}
                            <input
                              type="file"
                              accept="image/jpeg,image/png,image/webp"
                              className="hidden"
                              onChange={(event) =>
                                selectEditFlavorImage(event.target.files?.[0])
                              }
                            />
                          </label>
                          <UiButton variant="plain"
                            type="button"
                            role="switch"
                            aria-checked={editFlavorActive}
                            onClick={() =>
                              setEditFlavorActive((current) => !current)
                            }
                            className={`rounded-xl border px-2 py-2 text-xs font-black ${
                              editFlavorActive
                                ? 'border-nw-border bg-nw-ok-bg text-nw-ok'
                                : 'border-nw-border bg-nw-surface text-nw-muted'
                            }`}
                          >
                            {editFlavorActive ? 'ظاهرة ومتاحة' : 'متوقفة مؤقتًا'}
                          </UiButton>
                        </div>

                        {editFlavorImagePreview && (
                          <img
                            src={editFlavorImagePreview}
                            alt="معاينة صورة النكهة الجديدة"
                            className="h-20 w-full rounded-xl bg-nw-surface object-contain"
                          />
                        )}

                        {!editFlavorActive && flavor.onHandQuantity > 0 && (
                          <p className="rounded-xl bg-nw-warn-bg p-2 text-xs font-bold leading-4 text-nw-warn">
                            إيقاف النكهة يخفيها عن العملاء فقط؛ رصيدها وحركاتها سيبقيان محفوظين.
                          </p>
                        )}

                        {flavorConflict && (
                          <ProductEditConflictPanel
                            rows={flavorConflictRows()}
                            statusChange={
                              flavorOpened && flavorConflict.isActive !== flavorOpened.active
                                ? { mine: editFlavorActive, current: flavorConflict.isActive }
                                : undefined
                            }
                            formatValue={(_row, value) => (value === '' || value == null ? '—' : String(value))}
                            onReapply={reapplyFlavorEdits}
                          />
                        )}

                        <div className="grid grid-cols-2 gap-2">
                          <UiButton variant="plain"
                            type="button"
                            disabled={isUpdatingFlavor}
                            onClick={() => void saveFlavorChanges(flavor)}
                            className="rounded-xl bg-nw-primary py-2.5 text-xs font-black text-nw-on-primary disabled:opacity-50"
                          >
                            {isUpdatingFlavor ? 'جاري الحفظ...' : 'حفظ التعديل'}
                          </UiButton>
                          <UiButton variant="plain"
                            type="button"
                            disabled={isUpdatingFlavor}
                            onClick={cancelFlavorEdit}
                            className="rounded-xl bg-nw-mute-bg py-2.5 text-xs font-bold text-nw-text"
                          >
                            إلغاء
                          </UiButton>
                        </div>
                      </div>
                    )}

                    {!isEditingFlavor && (
                      <UiButton variant="plain"
                        type="button"
                        onClick={() => {
                          onClose();
                          openModal('receive_goods', { productId: flavor.id });
                        }}
                        className="mt-2 w-full rounded-xl border border-nw-border bg-nw-info-bg py-2 text-xs font-black text-nw-info"
                      >
                        استلام مخزون لهذه النكهة
                      </UiButton>
                    )}
                  </div>
                );
              })}
            </div>
          ) : (
            <p className="mt-3 rounded-xl border border-dashed border-nw-border p-3 text-center text-xs font-bold text-nw-muted">
              لا توجد نكهات بعد. أضف الأولى وسيبقى السعر موحدًا تلقائيًا.
            </p>
          )}
        </Card>
      )}

      <Card padded={false} className="rounded-2xl border border-nw-border    p-3.5">
        <div className="mb-3 flex items-center gap-2">
          <ReceiptText className="h-4 w-4 text-nw-ok" />
          <div>
            <h4 className="font-black text-nw-text">الأسعار والربحية</h4>
            <p className="text-xs text-nw-muted">
              سعر البيع للوحدة المحددة: {unitsPerSalePackage===1?product.unit:'طرد'}
            </p>
          </div>
        </div>

        <div className="grid grid-cols-3 gap-2">
          <PriceMetric
            label={`تكلفة ${unitsPerSalePackage===1?product.unit:'الطرد'}`}
            value={salePackageCost}
            color="text-nw-warn"
          />
          <PriceMetric
            label="سعر بيع الطرد"
            value={salePackagePrice}
            color="text-nw-info"
          />
          <TextMetric
            label="طرد البيع الأدنى"
            value={
              needsSalePackageSetup
                ? 'بحاجة ضبط'
                : `طرد × ${unitsPerSalePackage} ${product.unit}`
            }
            color={
              needsSalePackageSetup
                ? 'text-nw-bad'
                : 'text-nw-info'
            }
          />
        </div>

        {needsSalePackageSetup ? (
          <div className="mt-2 rounded-xl border border-nw-border bg-nw-warn-bg p-2.5 text-xs font-bold text-nw-warn">
            حدّد طرد بيع الجملة وعدد {product.unit} وسعر الطرد قبل إظهار
            المنتج للزبائن.
          </div>
        ) : (
          <div className="mt-2">
            <ProfitMetric
              label={`ربح ${unitsPerSalePackage===1?product.unit:'الطرد'}`}
              profit={salePackageProfit.profitPerUnit}
              margin={salePackageProfit.marginPercentage}
            />
          </div>
        )}

        {!needsSalePackageSetup && salePackageProfit.isLoss && (
          <div className="mt-2 flex items-start gap-2 rounded-xl border border-nw-border bg-nw-bad-bg p-2.5 text-xs font-bold text-nw-bad">
            <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />
            سعر بيع الطرد أقل من تكلفته الحالية.
          </div>
        )}
      </Card>

      <Card padded={false} className="rounded-2xl border border-nw-border bg-nw-surface p-3.5">
        <div className="mb-3 flex items-center gap-2">
          <Layers3 className="h-4 w-4 text-nw-info" />
          <div>
            <h4 className="font-black text-nw-text">طرد شراء المورد</h4>
            <p className="text-xs text-nw-muted">
              التحويل المعتمد إلى وحدة البيع
            </p>
          </div>
        </div>
        <div className="grid grid-cols-3 gap-2">
          <TextMetric
            label="الطرد"
            value={(product.unitsPerPackage||1)===1?product.unit:'طرد'}
          />
          <TextMetric
            label="محتوى الطرد"
            value={`${product.unitsPerPackage || 1} ${product.unit}`}
            color="text-nw-warn"
          />
          <TextMetric
            label="سعر الشراء"
            value={`${formatJod(
              product.defaultPurchasePrice ||
              product.costPrice * (product.unitsPerPackage || 1)
            )} ${CURRENCY}`}
            color="text-nw-ok"
          />
        </div>
      </Card>

      <Card padded={false}
        className="rounded-2xl border border-nw-border bg-nw-surface p-3.5"
        data-flavor-family-stock-summary={isFlavorFamily ? 'true' : undefined}
      >
        <div className="mb-3 flex items-center gap-2">
          <Boxes className="h-4 w-4 text-nw-info" />
          <div>
            <h4 className="font-black text-nw-text">
              {isFlavorFamily ? 'إجمالي مخزون النكهات' : 'الرصيد الحالي'}
            </h4>
            <p className="text-xs text-nw-muted">
              {isFlavorFamily
                ? 'محسوب للعرض فقط من أرصدة النكهات المستقلة'
                : 'يتغير من الاستلام والطلبات والجرد المعتمد'}
            </p>
          </div>
        </div>
        {isFlavorFamily && !familyInventorySummary.hasCompatiblePackaging ? (
          <p className="rounded-xl border border-nw-border bg-nw-warn-bg p-2.5 text-xs font-bold leading-4 text-nw-warn">
            أحجام طرود النكهات غير متطابقة؛ راجع رصيد كل نكهة بدل عرض مجموع مضلل.
          </p>
        ) : (
          <div className="grid grid-cols-3 gap-2">
            <TextMetric
              label="الموجود"
              value={inventoryOnHand.cartonFormatted}
              color="text-nw-warn"
            />
            <TextMetric
              label="المحجوز"
              value={
                isFlavorFamily
                  ? familyReserved.cartonFormatted
                  : `${familyInventoryProduct.reservedQuantity} ${product.unit}`
              }
              color="text-nw-warn"
            />
            <TextMetric
              label={isFlavorFamily ? 'إجمالي المتاح' : 'المتاح'}
              value={inventoryAvailable.cartonFormatted}
              color="text-nw-ok"
            />
          </div>
        )}
        <div className="mt-2 grid grid-cols-2 gap-2 rounded-xl border border-nw-border bg-nw-surface-2 p-2.5">
          <div>
            <span className="block text-xs font-bold text-nw-muted">
              تنبيه النقص
            </span>
            <strong className="text-xs text-nw-warn">
              {reorderSalePackages} طرد
            </strong>
          </div>
          <div>
            <span className="block text-xs font-bold text-nw-muted">
              سقف المستودع
            </span>
            <strong className="text-xs text-nw-text">
              {maxStockSalePackages === undefined
                ? 'غير محدد'
                : `${maxStockSalePackages} طرد`}
            </strong>
          </div>
        </div>
      </Card>

      <div className="grid grid-cols-2 gap-2">
        <UiButton variant="plain"
          type="button"
          onClick={() => {
            onClose();
            openModal('edit_product', product);
          }}
          className="flex items-center justify-center gap-1.5 rounded-xl bg-nw-primary py-3 font-black text-nw-on-primary"
        >
          <Edit3 className="h-4 w-4" />
          تعديل البيانات
        </UiButton>
        <UiButton variant="plain"
          type="button"
          onClick={() => setShowVisibilityConfirm(true)}
          className="flex items-center justify-center gap-1.5 rounded-xl border border-nw-border bg-nw-surface py-3 font-bold text-nw-text"
        >
          {product.status === 'hidden' ? (
            <Eye className="h-4 w-4 text-nw-ok" />
          ) : (
            <EyeOff className="h-4 w-4 text-nw-warn" />
          )}
          {product.status === 'hidden' ? 'إظهار المنتج' : 'إخفاء المنتج'}
        </UiButton>
      </div>

      {/* Owner only; the database refuses every other role as well. */}
      {!isFlavorFamily&&canUseSupplierReplacement(roles,roleName)&&<UiButton onClick={()=>openModal('supplier_replacement',{productId:product.id})}>استبدال المورد والمعلّق</UiButton>}
      {roleName === 'owner' && (isFlavorFamily ? flavors.length > 0 : true) && (
        showCostCorrection ? (
          <ProductCostCorrectionPanel
            targets={isFlavorFamily
              ? flavors.map((flavor) => ({ id: flavor.id, name: flavor.flavorNameAr || flavor.nameAr, unit: flavor.unit }))
              : [{ id: product.id, name: product.nameAr, unit: product.unit }]}
            onClose={() => setShowCostCorrection(false)}
            onCorrected={() => {
              setShowCostCorrection(false);
              setToast('تم تصحيح التكلفة وتسجيل السبب.', 'success');
              void refreshProductsFromSupabase();
            }}
          />
        ) : (
          <UiButton type="button" onClick={() => setShowCostCorrection(true)} className="justify-self-start">
            تصحيح التكلفة
          </UiButton>
        )
      )}

      {showVisibilityConfirm && (
        <div className="rounded-2xl border border-nw-border bg-nw-warn-bg p-3.5">
          <div className="flex items-start gap-2">
            <Tag className="mt-0.5 h-4 w-4 shrink-0 text-nw-warn" />
            <div>
              <h4 className="font-black text-nw-warn">
                {product.status === 'hidden'
                  ? 'إعادة إظهار المنتج؟'
                  : 'هل تريد إخفاء المنتج؟'}
              </h4>
              <p className="mt-1 text-xs leading-5 text-nw-muted">
                لن نحذف حركاته أو رصيده. سيتم فقط تغيير حالة ظهوره في
                الكتالوج.
              </p>
            </div>
          </div>
          <div className="mt-3 flex gap-2">
            <UiButton variant="plain"
              type="button"
              onClick={changeVisibility}
              disabled={isUpdatingVisibility}
              className="flex-1 rounded-xl bg-nw-warn-bg py-2.5 font-black text-nw-muted disabled:opacity-50"
            >
              {isUpdatingVisibility ? 'جاري الحفظ...' : 'نعم، تأكيد'}
            </UiButton>
            <UiButton variant="plain"
              type="button"
              onClick={() => setShowVisibilityConfirm(false)}
              className="flex-1 rounded-xl bg-nw-mute-bg py-2.5 font-bold text-nw-text"
            >
              إلغاء
            </UiButton>
          </div>
        </div>
      )}

      <BarcodeCameraCaptureModal
        isOpen={barcodeCameraTarget !== null}
        onClose={() => setBarcodeCameraTarget(null)}
        onCapture={captureFlavorBarcode}
        startScanner={startBarcodeScanner}
      />
    </FormFields>
  );
};

const PriceMetric: React.FC<{
  label: string;
  value: number;
  color: string;
}> = ({ label, value, color }) => (
  <div className="rounded-xl border border-nw-border bg-nw-surface-2 p-2 text-center">
    <span className="block text-xs font-bold text-nw-muted">{label}</span>
    <strong className={`mt-1 block text-xs ${color}`}>
      {formatJod(value)} {CURRENCY}
    </strong>
  </div>
);

const ProfitMetric: React.FC<{
  label: string;
  profit: number;
  margin: number;
}> = ({ label, profit, margin }) => (
  <div className="rounded-xl border border-nw-border bg-nw-surface-2 p-2.5">
    <span className="text-xs font-bold text-nw-muted">{label}</span>
    <div
      className={`mt-1 flex items-center justify-between ${
        profit >= 0 ? 'text-nw-ok' : 'text-nw-bad'
      }`}
    >
      <strong className="text-xs">
        {formatJod(profit)} {CURRENCY}
      </strong>
      <span className="font-mono text-xs">%{margin.toFixed(1)}</span>
    </div>
  </div>
);

const TextMetric: React.FC<{
  label: string;
  value: string;
  color?: string;
}> = ({ label, value, color = 'text-nw-text' }) => (
  <div className="min-w-0 rounded-xl border border-nw-border bg-nw-surface-2 p-2 text-center">
    <span className="block text-xs font-bold text-nw-muted">{label}</span>
    <strong className={`mt-1 block break-words text-xs ${color}`}>
      {value}
    </strong>
  </div>
);

