          </div>

          <div className="space-y-2">
            <UiButton variant="plain"
              type="button"
              onClick={() => setShowImageUrlInput((value) => !value)}
              className="mt-2 text-xs font-bold text-nw-muted hover:text-nw-info"
            >
              {showImageUrlInput
